/* ============================================================
   Builder360 ERP/CRM — Design System
   Premium ultra-modern corporate SaaS. Light + Dark.
   ============================================================ */

/* ---------- Tokens ---------- */
:root {
  --font-display: "Plus Jakarta Sans", system-ui, sans-serif;
  --font-ui: "Manrope", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  /* spacing scale */
  --s1: 4px;  --s2: 8px;  --s3: 12px; --s4: 16px;
  --s5: 20px; --s6: 24px; --s7: 32px; --s8: 40px; --s9: 56px;

  --r-sm: 8px; --r-md: 12px; --r-lg: 16px; --r-xl: 22px; --r-pill: 999px;

  /* accent — indigo family (shared both themes, tuned per theme below) */
  --accent: #4f46e5;
  --accent-soft: #eef0fe;
  --accent-press: #4338ca;
  --accent-2: #0ea5a4;       /* teal secondary */
  --accent-grad: linear-gradient(135deg, #6366f1 0%, #4f46e5 55%, #4338ca 100%);

  /* semantic */
  --green: #15a657;  --green-soft: #e4f7ec;
  --orange: #e08600; --orange-soft: #fdf0db;
  --red: #dc2f3a;    --red-soft: #fde7e8;
  --blue: #2570eb;   --blue-soft: #e7f0fe;
  --violet: #7c3aed; --violet-soft: #f0e9fe;
  --slate: #64748b;  --slate-soft: #eef1f5;
}

/* LIGHT (default) */
:root, [data-theme="light"] {
  --bg: #f4f5f8;
  --bg-grad: radial-gradient(1200px 600px at 100% -10%, #eef0fe 0%, rgba(238,240,254,0) 55%), #f4f5f8;
  --surface: #ffffff;
  --surface-2: #fafbfc;
  --surface-3: #f3f4f7;
  --sidebar: #ffffff;
  --sidebar-ink: #11141d;
  --border: #e7e9ee;
  --border-strong: #d6d9e0;
  --text: #11141d;
  --text-2: #5a6072;
  --text-3: #8d93a4;
  --shadow-sm: 0 1px 2px rgba(17,20,29,.05), 0 1px 1px rgba(17,20,29,.03);
  --shadow-md: 0 4px 14px rgba(17,20,29,.07), 0 1px 3px rgba(17,20,29,.05);
  --shadow-lg: 0 18px 50px -12px rgba(17,20,29,.22), 0 6px 18px rgba(17,20,29,.08);
  --ring: 0 0 0 3px rgba(79,70,229,.18);
  --grid-line: rgba(17,20,29,.06);
}

/* DARK */
[data-theme="dark"] {
  --accent: #6d68f0;
  --accent-soft: rgba(109,104,240,.16);
  --accent-press: #837ef5;
  --accent-grad: linear-gradient(135deg, #7c78f6 0%, #5b54e8 60%, #4f46e5 100%);

  --green: #2fce76;  --green-soft: rgba(47,206,118,.15);
  --orange: #f2a03d; --orange-soft: rgba(242,160,61,.15);
  --red: #f0606b;    --red-soft: rgba(240,96,107,.15);
  --blue: #5a96f5;   --blue-soft: rgba(90,150,245,.15);
  --violet: #a684f7; --violet-soft: rgba(166,132,247,.16);
  --slate: #94a0b4;  --slate-soft: rgba(148,160,180,.14);

  --bg: #0a0c11;
  --bg-grad: radial-gradient(1100px 560px at 100% -10%, rgba(79,70,229,.16) 0%, rgba(10,12,17,0) 55%), #0a0c11;
  --surface: #14171f;
  --surface-2: #181c25;
  --surface-3: #1e222d;
  --sidebar: #0e1016;
  --sidebar-ink: #f3f5f9;
  --border: #242833;
  --border-strong: #323744;
  --text: #f1f3f8;
  --text-2: #9aa1b1;
  --text-3: #6b7283;
  --shadow-sm: 0 1px 2px rgba(0,0,0,.4);
  --shadow-md: 0 6px 18px rgba(0,0,0,.42);
  --shadow-lg: 0 24px 60px -16px rgba(0,0,0,.7), 0 8px 24px rgba(0,0,0,.5);
  --ring: 0 0 0 3px rgba(109,104,240,.3);
  --grid-line: rgba(255,255,255,.06);
}

/* ---------- Reset / base ---------- */
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; height: 100%; }
body {
  font-family: var(--font-ui);
  background: var(--bg);
  color: var(--text);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  font-size: 14px;
  line-height: 1.45;
}
#root { height: 100vh; }
::selection { background: var(--accent-soft); }
h1,h2,h3,h4 { font-family: var(--font-display); margin: 0; letter-spacing: -.02em; font-weight: 700; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; }
.mono { font-family: var(--font-mono); font-feature-settings: "tnum" 1; letter-spacing: -.02em; }
.tnum { font-variant-numeric: tabular-nums; }

/* scrollbars */
*::-webkit-scrollbar { width: 10px; height: 10px; }
*::-webkit-scrollbar-thumb { background: var(--border-strong); border-radius: 99px; border: 3px solid transparent; background-clip: padding-box; }
*::-webkit-scrollbar-thumb:hover { background: var(--text-3); background-clip: padding-box; border: 3px solid transparent; }
*::-webkit-scrollbar-track { background: transparent; }

/* ============================================================
   App layout
   ============================================================ */
.app { display: flex; height: 100vh; overflow: hidden; background: var(--bg-grad); }

/* ---------- Sidebar ---------- */
.sidebar {
  width: 264px; flex: 0 0 264px; height: 100vh;
  background: var(--sidebar); border-right: 1px solid var(--border);
  display: flex; flex-direction: column; transition: width .22s cubic-bezier(.4,0,.2,1);
  position: relative; z-index: 30;
}
.sidebar.collapsed { width: 76px; flex-basis: 76px; }
.sb-brand { display: flex; align-items: center; gap: 11px; padding: 18px 18px 14px; }
.sb-logo {
  width: 38px; height: 38px; border-radius: 11px; flex: 0 0 38px;
  background: var(--accent-grad); display: grid; place-items: center;
  box-shadow: 0 6px 16px -4px rgba(79,70,229,.5); color: #fff;
}
.sb-logo svg { width: 21px; height: 21px; }
.sb-brand-name { font-family: var(--font-display); font-weight: 800; font-size: 16.5px; letter-spacing: -.03em; color: var(--sidebar-ink); white-space: nowrap; }
.sb-brand-sub { font-size: 10.5px; color: var(--text-3); font-weight: 600; letter-spacing: .04em; text-transform: uppercase; margin-top: -1px; }

.sb-search {
  margin: 4px 14px 8px; height: 36px; border-radius: var(--r-sm);
  background: var(--surface-3); border: 1px solid transparent;
  display: flex; align-items: center; gap: 8px; padding: 0 10px; color: var(--text-3);
  font-size: 12.5px; cursor: text;
}
.sb-search kbd {
  margin-left: auto; font-family: var(--font-ui); font-size: 10px; font-weight: 700;
  background: var(--surface); border: 1px solid var(--border); border-radius: 5px; padding: 1px 5px; color: var(--text-3);
}

.sb-nav { flex: 1; overflow-y: auto; padding: 4px 12px 16px; }
.sb-nav::-webkit-scrollbar { width: 6px; }
.sb-group-label {
  font-size: 10px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase;
  color: var(--text-3); padding: 14px 10px 6px; white-space: nowrap;
}
.collapsed .sb-group-label { opacity: 0; height: 0; padding: 6px 0; overflow: hidden; }
.nav-item {
  display: flex; align-items: center; gap: 11px; height: 37px; padding: 0 11px;
  border-radius: 9px; color: var(--text-2); font-weight: 600; font-size: 13px;
  cursor: pointer; position: relative; margin-bottom: 1px; white-space: nowrap;
  transition: background .13s, color .13s;
}
.nav-item:hover { background: var(--surface-3); color: var(--text); }
.nav-item .ni-ic { width: 18px; height: 18px; flex: 0 0 18px; opacity: .82; }
.nav-item.active { background: var(--accent-soft); color: var(--accent); }
.nav-item.active .ni-ic { opacity: 1; }
.nav-item.active::before {
  content: ""; position: absolute; left: -12px; top: 50%; transform: translateY(-50%);
  width: 3px; height: 18px; border-radius: 0 3px 3px 0; background: var(--accent);
}
.nav-badge { margin-left: auto; font-size: 10.5px; font-weight: 800; background: var(--red); color: #fff;
  border-radius: 99px; min-width: 18px; height: 18px; padding: 0 5px; display: grid; place-items: center; }
.nav-item.active .nav-badge { background: var(--accent); }
.collapsed .nav-label, .collapsed .nav-badge, .collapsed .sb-search kbd, .collapsed .sb-search span { display: none; }
.collapsed .sb-brand-name, .collapsed .sb-brand-sub { display: none; }
.collapsed .nav-item { justify-content: center; padding: 0; }
.collapsed .sb-search { justify-content: center; }

.sb-foot { padding: 10px 14px 14px; border-top: 1px solid var(--border); }

/* ---------- Topbar ---------- */
.main { flex: 1; display: flex; flex-direction: column; min-width: 0; height: 100vh; }
.topbar {
  height: 62px; flex: 0 0 62px; display: flex; align-items: center; gap: 14px;
  padding: 0 22px; border-bottom: 1px solid var(--border);
  background: color-mix(in srgb, var(--surface) 78%, transparent);
  backdrop-filter: blur(14px); position: relative; z-index: 20;
}
.icon-btn {
  width: 36px; height: 36px; border-radius: 9px; border: 1px solid var(--border);
  background: var(--surface); display: grid; place-items: center; color: var(--text-2);
  position: relative; transition: .13s;
}
.icon-btn:hover { color: var(--text); border-color: var(--border-strong); background: var(--surface-2); }
.icon-btn .dot { position: absolute; top: 7px; right: 8px; width: 7px; height: 7px; border-radius: 99px; background: var(--red); border: 2px solid var(--surface); }
.topbar-search {
  flex: 1; max-width: 440px; height: 38px; border-radius: 10px; background: var(--surface-3);
  border: 1px solid var(--border); display: flex; align-items: center; gap: 9px; padding: 0 12px;
  color: var(--text-3); font-size: 13px;
}
.topbar-search input { border: none; background: none; outline: none; flex: 1; color: var(--text); font-family: inherit; font-size: 13px; }
.topbar-search kbd { font-family: var(--font-ui); font-size: 10px; font-weight: 700; background: var(--surface); border: 1px solid var(--border); border-radius: 5px; padding: 1px 6px; color: var(--text-3); }

.proj-pill {
  height: 38px; border-radius: 10px; border: 1px solid var(--border); background: var(--surface);
  display: flex; align-items: center; gap: 9px; padding: 0 12px; font-weight: 700; font-size: 13px; color: var(--text);
}
.proj-pill .pp-dot { width: 9px; height: 9px; border-radius: 3px; }
.proj-pill:hover { border-color: var(--border-strong); }

.avatar {
  width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center;
  font-weight: 800; font-size: 13px; color: #fff; background: var(--accent-grad); flex: 0 0 36px;
}
.user-chip { display: flex; align-items: center; gap: 10px; padding: 3px 10px 3px 4px; border-radius: 11px; border: 1px solid transparent; }
.user-chip:hover { background: var(--surface-3); }
.top-project-menu { max-height: min(72vh, 680px); overflow-y: auto; overscroll-behavior: contain; }
.top-role-menu { max-height: min(430px, calc(100vh - 92px)); overflow-y: auto; overscroll-behavior: contain; }
.top-role-menu .nav-item,
.top-project-menu .nav-item { min-width: 0; }
.top-role-menu .nav-item > div,
.top-project-menu .nav-item > div { min-width: 0; }
.top-role-menu .nav-item { min-height: 39px; padding-top: 5px; padding-bottom: 5px; }
.top-role-menu .avatar { width: 26px !important; height: 26px !important; flex-basis: 26px !important; border-radius: 9px; font-size: 12px; }
.top-role-menu .nav-item .cell-sub { font-size: 11.5px; line-height: 1.15; }
.top-role-strip {
  flex: 0 0 auto;
  position: relative;
  z-index: 19;
  display: grid;
  grid-template-columns: minmax(180px, 260px) minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding: 10px 22px;
  border-bottom: 1px solid var(--border);
  background: color-mix(in srgb, var(--surface) 94%, transparent);
  backdrop-filter: blur(14px);
  box-shadow: 0 12px 28px -26px rgba(15, 23, 42, .5);
}
.top-role-strip-head {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.top-role-strip-list {
  min-width: 0;
  display: flex;
  gap: 8px;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  padding: 1px 2px 4px;
  scrollbar-width: thin;
}
.top-role-chip {
  flex: 0 0 154px;
  min-width: 0;
  height: 48px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 10px;
  border: 1px solid var(--border);
  border-radius: 13px;
  background: var(--surface);
  color: var(--text);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: .16s ease;
}
.top-role-chip:hover {
  background: var(--surface-2);
  border-color: var(--border-strong);
  transform: translateY(-1px);
}
.top-role-chip:focus-visible {
  outline: 3px solid var(--ring);
  outline-offset: 2px;
}
.top-role-chip.active {
  background: var(--accent-soft);
  border-color: color-mix(in srgb, var(--accent) 34%, var(--border));
  color: var(--accent);
}
.top-role-chip:disabled {
  opacity: .58;
  cursor: wait;
  transform: none;
}
.top-role-chip-text {
  min-width: 0;
  display: grid;
  line-height: 1.1;
}
.top-role-chip-text b,
.top-role-chip-text small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.top-role-chip-text b { font-size: 12.5px; font-weight: 800; }
.top-role-chip-text small { margin-top: 2px; color: var(--text-3); font-size: 11.5px; font-weight: 650; }
@media (max-width: 860px) {
  .top-role-strip {
    grid-template-columns: 1fr;
    padding: 10px 14px;
  }
  .top-role-chip { flex-basis: 148px; }
}

.content { flex: 1; overflow-y: auto; overflow-x: hidden; }
.page { padding: 26px 28px 60px; max-width: 1500px; margin: 0 auto; }
.page-wide { max-width: 1760px; }

/* ---------- Page header ---------- */
.crumbs { display: flex; align-items: center; gap: 7px; font-size: 12px; color: var(--text-3); font-weight: 600; margin-bottom: 12px; }
.crumbs .sep { opacity: .5; }
.page-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; margin-bottom: 22px; flex-wrap: wrap; }
.page-title { font-size: 25px; font-weight: 800; letter-spacing: -.035em; }
.page-sub { color: var(--text-2); font-size: 13.5px; margin-top: 3px; max-width: 620px; }
.head-actions { display: flex; align-items: center; gap: 9px; }

/* ---------- Buttons ---------- */
.btn {
  height: 38px; padding: 0 15px; border-radius: 9px; border: 1px solid var(--border-strong);
  background: var(--surface); color: var(--text); font-weight: 700; font-size: 13px;
  display: inline-flex; align-items: center; gap: 8px; transition: .13s; white-space: nowrap;
}
.btn:hover { background: var(--surface-2); border-color: var(--text-3); }
.btn svg { width: 16px; height: 16px; }
.btn-primary { background: var(--accent); border-color: transparent; color: #fff; box-shadow: 0 4px 12px -3px rgba(79,70,229,.45); }
.btn-primary:hover { background: var(--accent-press); border-color: transparent; }
.btn-ghost { background: transparent; border-color: transparent; color: var(--text-2); }
.btn-ghost:hover { background: var(--surface-3); color: var(--text); }
.btn-sm { height: 32px; padding: 0 11px; font-size: 12.5px; border-radius: 8px; }
.btn-success { background: var(--green); border-color: transparent; color: #fff; }
.btn-danger { background: var(--red); border-color: transparent; color: #fff; }

/* ---------- Cards ---------- */
.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--r-lg); box-shadow: var(--shadow-sm); }
.card-pad { padding: 20px; }
.card-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 16px 18px; border-bottom: 1px solid var(--border); }
.card-title { font-family: var(--font-display); font-weight: 700; font-size: 14.5px; letter-spacing: -.02em; }
.card-sub { font-size: 12px; color: var(--text-3); margin-top: 2px; }

.grid { display: grid; gap: 16px; }
.g-2 { grid-template-columns: repeat(2,1fr); }
.g-3 { grid-template-columns: repeat(3,1fr); }
.g-4 { grid-template-columns: repeat(4,1fr); }
.g-6 { grid-template-columns: repeat(6,1fr); }
@media (max-width: 1200px){ .g-4 { grid-template-columns: repeat(2,1fr);} .g-6{grid-template-columns:repeat(3,1fr);} .g-3{grid-template-columns:repeat(2,1fr);} }

.dash-page .page-head { align-items: flex-start; gap: 16px; overflow: visible; }
.dash-page .head-actions { flex-wrap: wrap; justify-content: flex-end; overflow: visible; position: relative; z-index: 20; }
.dash-stat-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; margin-bottom: 16px; }
.dash-section-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; align-items: start; }
.dash-chart-grid,
.dash-table-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; align-items: start; margin-bottom: 16px; }
.dash-alert-grid { display: grid; grid-template-columns: 1fr; gap: 16px; margin-bottom: 16px; }
.dash-quick-actions { display: flex; flex-wrap: wrap; gap: 10px; margin: -4px 0 16px; }
.dash-stat-grid .stat { min-height: 176px; display: flex; flex-direction: column; justify-content: space-between; }
.stat-clickable { cursor: pointer; transition: transform .14s ease, box-shadow .14s ease, border-color .14s ease; }
.stat-clickable:hover { transform: translateY(-1px); box-shadow: var(--shadow-md); border-color: color-mix(in srgb, var(--accent) 32%, var(--border)); }
.stat-clickable:focus-visible,
.dash-row.clickable:focus-visible,
.dash-period-btn:focus-visible,
.dash-period-option:focus-visible,
.dash-chart-row.clickable:focus-visible,
.dash-table tr.clickable:focus-visible { outline: 3px solid color-mix(in srgb, var(--accent) 28%, transparent); outline-offset: 2px; }
.dash-section-card { overflow: visible; }
.dash-section-card .card-head { gap: 14px; align-items: flex-start; }
.dash-section-card .card-head > div:first-child { min-width: 0; }
.dash-section-card .card-head > div:last-child { flex-wrap: wrap; justify-content: flex-end; }
.dash-row { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 10px 0; }
.dash-row.clickable { cursor: pointer; border-radius: 12px; padding-left: 8px; padding-right: 8px; margin-left: -8px; margin-right: -8px; }
.dash-row.clickable:hover { background: var(--surface-2); }
.dash-row-title { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dash-row-sub { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dash-period { position: relative; overflow: visible; }
.dash-period-range { margin-left: 2px; color: var(--text-3); font-size: 11px; font-weight: 700; max-width: 140px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dash-period-btn:disabled { opacity: .65; cursor: wait; }
.dash-period-scrim { position: fixed; inset: 0; z-index: 90; }
.dash-period-menu { position: absolute; left: 0; right: auto; top: calc(100% + 8px); width: min(330px, calc(100vw - 28px)); max-height: min(520px, calc(100vh - 150px)); overflow: auto; z-index: 91; padding: 10px; box-shadow: var(--shadow-lg); border-radius: 18px; }
.dash-period-option { appearance: none; -webkit-appearance: none; border: 0; background: transparent; width: 100%; min-height: 40px; border-radius: 10px; display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 9px 10px; font: inherit; font-weight: 750; color: var(--text-2); cursor: pointer; }
.dash-period-option span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.dash-period-option:hover,
.dash-period-option.active { background: var(--accent-soft); color: var(--accent); }
.dash-custom-range { border-top: 1px solid var(--border); margin-top: 8px; padding-top: 10px; display: grid; gap: 9px; }
.dash-custom-range label { display: grid; gap: 5px; font-size: 11px; font-weight: 800; color: var(--text-3); text-transform: uppercase; letter-spacing: .04em; }
.dash-custom-range input { width: 100%; height: 38px; border: 1px solid var(--border); border-radius: 10px; padding: 0 10px; background: var(--surface); color: var(--text); font: inherit; }
.dash-field-error { color: var(--red); background: var(--red-soft); border-radius: 10px; padding: 8px 10px; font-size: 12px; font-weight: 750; }
.dash-chart-card,
.dash-table-card,
.dash-alert-card { min-width: 0; overflow: hidden; }
.dash-chart-bars { display: grid; gap: 12px; }
.dash-chart-row { display: grid; grid-template-columns: minmax(96px, 1fr) minmax(120px, 2fr) auto; gap: 12px; align-items: center; border-radius: 12px; padding: 4px 6px; margin: 0 -6px; }
.dash-chart-row.clickable { cursor: pointer; }
.dash-chart-row.clickable:hover,
.dash-table tr.clickable:hover { background: var(--surface-2); }
.dash-chart-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 750; color: var(--text-2); }
.dash-chart-track { height: 12px; border-radius: 999px; background: var(--surface-3); overflow: hidden; }
.dash-chart-fill { height: 100%; border-radius: inherit; background: var(--accent); }
.dash-chart-fill.b-green { background: var(--green); }
.dash-chart-fill.b-orange { background: var(--orange); }
.dash-chart-fill.b-red { background: var(--red); }
.dash-chart-fill.b-blue { background: var(--blue); }
.dash-chart-fill.b-violet { background: var(--violet); }
.dash-chart-fill.b-slate { background: var(--text-3); }
.dash-chart-value { font-family: var(--font-mono); font-weight: 850; color: var(--text); text-align: right; white-space: nowrap; }
.dash-table-wrap { width: 100%; overflow-x: auto; }
.dash-table { width: 100%; min-width: 560px; border-collapse: collapse; }
.dash-table th { text-align: left; color: var(--text-3); font-size: 11px; text-transform: uppercase; letter-spacing: .05em; padding: 12px 16px; border-bottom: 1px solid var(--border); }
.dash-table td { padding: 12px 16px; border-bottom: 1px solid var(--border); vertical-align: middle; }
.dash-table tr:last-child td { border-bottom: 0; }
.dash-table tr.clickable { cursor: pointer; }
@media (max-width: 1180px) {
  .dash-stat-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dash-section-grid { grid-template-columns: 1fr; }
  .dash-chart-grid,
  .dash-table-grid { grid-template-columns: 1fr; }
}
@media (max-width: 720px) {
  .dash-page .page-head { flex-direction: column; }
  .dash-page .head-actions { width: 100%; justify-content: flex-start; }
  .dash-stat-grid { grid-template-columns: 1fr; }
  .dash-row { align-items: flex-start; }
  .dash-period { width: 100%; }
  .dash-period-btn { width: 100%; justify-content: space-between; }
  .dash-period-menu { left: 0; right: auto; width: min(320px, calc(100vw - 28px)); }
  .dash-chart-row { grid-template-columns: 1fr; gap: 7px; }
  .dash-chart-value { text-align: left; }
  .dash-table { min-width: 500px; }
}

/* ---------- Stat card ---------- */
.stat { padding: 17px 18px; position: relative; overflow: hidden; }
.stat-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
.stat-ic { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; }
.stat-ic svg { width: 18px; height: 18px; }
.stat-label { font-size: 12px; color: var(--text-2); font-weight: 600; }
.stat-val { font-family: var(--font-display); font-weight: 800; font-size: 27px; letter-spacing: -.04em; line-height: 1.05; }
.stat-val .unit { font-size: 15px; color: var(--text-3); font-weight: 700; }
.stat-delta { display: inline-flex; align-items: center; gap: 3px; font-size: 11.5px; font-weight: 800; margin-top: 9px; padding: 2px 7px 2px 5px; border-radius: 99px; }
.stat-delta svg { width: 13px; height: 13px; }
.delta-up { color: var(--green); background: var(--green-soft); }
.delta-down { color: var(--red); background: var(--red-soft); }
.delta-flat { color: var(--slate); background: var(--slate-soft); }

/* ---------- Badges / chips ---------- */
.badge {
  display: inline-flex; align-items: center; gap: 5px; height: 22px; padding: 0 9px;
  border-radius: 99px; font-size: 11.5px; font-weight: 800; letter-spacing: -.01em; white-space: nowrap;
}
.badge .bdot { width: 6px; height: 6px; border-radius: 99px; background: currentColor; }
.b-green { color: var(--green); background: var(--green-soft); }
.b-orange { color: var(--orange); background: var(--orange-soft); }
.b-red { color: var(--red); background: var(--red-soft); }
.b-blue { color: var(--blue); background: var(--blue-soft); }
.b-violet { color: var(--violet); background: var(--violet-soft); }
.b-slate { color: var(--slate); background: var(--slate-soft); }
.b-accent { color: var(--accent); background: var(--accent-soft); }

.tag { display:inline-flex; align-items:center; gap:6px; height: 26px; padding: 0 11px; border-radius: 8px; background: var(--surface-3); border: 1px solid var(--border); font-size: 12px; font-weight: 600; color: var(--text-2); }

/* ---------- Filter bar ---------- */
.filterbar { display: flex; align-items: center; gap: 9px; margin-bottom: 16px; flex-wrap: wrap; }
.chip-select { height: 36px; padding: 0 11px; border-radius: 9px; border: 1px solid var(--border); background: var(--surface);
  display: inline-flex; align-items: center; gap: 8px; font-size: 12.5px; font-weight: 600; color: var(--text); }
.chip-select svg { width: 15px; height: 15px; color: var(--text-3); }
.chip-select:hover { border-color: var(--border-strong); }
.seg { display: inline-flex; background: var(--surface-3); border: 1px solid var(--border); border-radius: 9px; padding: 3px; gap: 2px; }
.seg button { height: 28px; padding: 0 12px; border: none; background: transparent; border-radius: 7px; font-size: 12.5px; font-weight: 700; color: var(--text-2); }
.seg button.on { background: var(--surface); color: var(--text); box-shadow: var(--shadow-sm); }

/* ---------- Table ---------- */
.tbl-wrap { overflow-x: auto; }
table.tbl { width: 100%; border-collapse: collapse; font-size: 13px; }
.tbl thead th {
  text-align: left; font-size: 11px; font-weight: 800; letter-spacing: .04em; text-transform: uppercase;
  color: var(--text-3); padding: 11px 16px; border-bottom: 1px solid var(--border); white-space: nowrap; position: sticky; top: 0; background: var(--surface);
}
.tbl tbody td { padding: 13px 16px; border-bottom: 1px solid var(--border); color: var(--text); vertical-align: middle; white-space: nowrap; }
.tbl tbody tr:last-child td { border-bottom: none; }
.tbl tbody tr { transition: background .1s; }
.tbl tbody tr:hover { background: var(--surface-2); }
.tbl .num { text-align: right; font-family: var(--font-mono); font-feature-settings: "tnum" 1; }
.linklike { appearance: none; -webkit-appearance: none; display: inline-flex; align-items: center; justify-content: center; min-height: 30px; padding: 0 12px; border: 1px solid var(--border); border-radius: 9px; background: var(--surface); color: var(--accent); font: 800 12.5px var(--font-ui); text-decoration: none; cursor: pointer; box-shadow: var(--shadow-sm); transition: color .16s ease, background .16s ease, border-color .16s ease, box-shadow .16s ease, transform .16s ease; }
.linklike:hover { color: var(--accent-press); border-color: color-mix(in srgb, var(--accent) 34%, var(--border)); background: var(--accent-soft); box-shadow: 0 10px 22px -18px var(--accent); }
.linklike:active { transform: translateY(1px); }
.linklike:disabled { opacity: .45; cursor: not-allowed; transform: none; box-shadow: none; }
.cell-strong { font-weight: 700; }
.cell-sub { color: var(--text-3); font-size: 11.5px; font-weight: 500; }
.avatar-sm { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; font-size: 11px; font-weight: 800; color: #fff; flex: 0 0 28px; }
.cell-user { display: flex; align-items: center; gap: 9px; }

/* progress */
.bar { height: 7px; border-radius: 99px; background: var(--surface-3); overflow: hidden; min-width: 70px; }
.bar > i { display: block; height: 100%; border-radius: 99px; background: var(--accent); }
.bar.green > i { background: var(--green); }
.bar.orange > i { background: var(--orange); }
.bar.red > i { background: var(--red); }

/* mini progress with label */
.prog-cell { display: flex; align-items: center; gap: 9px; }
.prog-cell .pv { font-size: 12px; font-weight: 700; min-width: 34px; font-family: var(--font-mono); }

/* ---------- Empty / loading ---------- */
.empty { display: grid; place-items: center; text-align: center; padding: 56px 20px; color: var(--text-3); }
.empty-ic { width: 56px; height: 56px; border-radius: 16px; background: var(--surface-3); display: grid; place-items: center; margin-bottom: 14px; color: var(--text-3); }
.empty h3 { font-size: 16px; color: var(--text); margin-bottom: 5px; }

.skel { background: linear-gradient(90deg, var(--surface-3) 25%, var(--surface-2) 37%, var(--surface-3) 63%); background-size: 400% 100%; animation: shimmer 1.3s infinite; border-radius: 7px; }
@keyframes shimmer { 0%{background-position:100% 0} 100%{background-position:-100% 0} }

/* ---------- Donut / charts helpers ---------- */
.legend { display: flex; flex-direction: column; gap: 9px; }
.legend-row { display: flex; align-items: center; gap: 9px; font-size: 12.5px; }
.legend-row .lk { width: 10px; height: 10px; border-radius: 3px; flex: 0 0 10px; }
.legend-row .lv { margin-left: auto; font-weight: 700; font-family: var(--font-mono); }

/* funnel */
.funnel-row { display: flex; align-items: center; gap: 14px; padding: 9px 0; }
.funnel-bar-wrap { flex: 1; height: 38px; border-radius: 10px; background: var(--surface-3); overflow: hidden; position: relative; }
.funnel-bar { height: 100%; border-radius: 10px; display: flex; align-items: center; padding: 0 14px; color: #fff; font-weight: 800; font-size: 13px; }

/* ---------- Toast ---------- */
.toast-wrap { position: fixed; bottom: 24px; right: 24px; z-index: 200; display: flex; flex-direction: column; gap: 10px; }
.toast { display: flex; align-items: center; gap: 11px; background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 12px 15px; box-shadow: var(--shadow-lg); min-width: 280px; animation: toastIn .25s cubic-bezier(.2,.8,.2,1); }
@keyframes toastIn { from { opacity: 0; transform: translateY(10px); } }
.toast-ic { width: 30px; height: 30px; border-radius: 8px; display: grid; place-items: center; flex: 0 0 30px; }

/* ---------- Modal / drawer ---------- */
.scrim { position: fixed; inset: 0; background: rgba(8,10,16,.5); backdrop-filter: blur(3px); z-index: 100; display: grid; place-items: center; padding: 24px; overflow-y: auto; animation: fade .18s; }
[data-theme="dark"] .scrim { background: rgba(0,0,0,.62); }
@keyframes fade { from { opacity: 0; } }
.drawer { position: fixed; top: 0; right: 0; height: 100vh; width: 480px; background: var(--surface); border-left: 1px solid var(--border); box-shadow: var(--shadow-lg); z-index: 101; display: flex; flex-direction: column; animation: drawerIn .28s cubic-bezier(.2,.8,.2,1); }
@keyframes drawerIn { from { transform: translateX(40px); opacity: .4; } }
.modal { width: 520px; max-width: 92vw; max-height: calc(100vh - 48px); overflow-y: auto; background: var(--surface); border: 1px solid var(--border); border-radius: var(--r-xl); box-shadow: var(--shadow-lg); animation: modalIn .22s cubic-bezier(.2,.8,.2,1); }
.modal-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; padding: 18px 22px; border-bottom: 1px solid var(--border); background: var(--surface); }
.modal-head h2 { margin: 0; font: 800 19px/1.2 var(--font-display); letter-spacing: -.02em; color: var(--text); }
.modal-head p { margin: 5px 0 0; max-width: 620px; font-size: 12px; line-height: 1.5; color: var(--text-2); }
.modal-head .icon-btn { flex: 0 0 auto; }
.modal .form-grid { padding: 18px 22px; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px 16px; align-items: start; }
.modal .form-grid label { display: block; min-width: 0; font-size: 11px; line-height: 1.25; font-weight: 800; letter-spacing: .025em; text-transform: uppercase; color: var(--text-3); }
.modal .form-grid input,
.modal .form-grid select,
.modal .form-grid textarea { display: block; width: 100%; box-sizing: border-box; margin-top: 7px; border: 1px solid var(--border-strong); border-radius: 9px; background: var(--surface); color: var(--text); font: 600 13px var(--font-ui); outline: none; transition: border-color .16s ease, box-shadow .16s ease, background .16s ease; }
.modal .form-grid input,
.modal .form-grid select { height: 40px; padding: 0 11px; }
.modal .form-grid textarea { min-height: 92px; padding: 10px 11px; line-height: 1.5; resize: vertical; }
.modal .form-grid input:disabled,
.modal .form-grid select:disabled,
.modal .form-grid textarea:disabled { opacity: .72; cursor: not-allowed; background: var(--surface-2); color: var(--text-2); }
.modal .form-grid input:focus,
.modal .form-grid select:focus,
.modal .form-grid textarea:focus { border-color: var(--accent); box-shadow: var(--ring); }
.modal .sys-note { margin: 0 22px 16px; padding: 11px 12px; border: 1px solid var(--border); border-radius: 11px; background: var(--surface-2); color: var(--text-2); font-size: 12px; line-height: 1.45; }
.modal-foot { position: sticky; bottom: 0; z-index: 2; display: flex; align-items: center; justify-content: flex-end; gap: 9px; padding: 14px 22px; border-top: 1px solid var(--border); background: color-mix(in srgb, var(--surface) 94%, transparent); backdrop-filter: blur(10px); }
@keyframes modalIn { from { transform: scale(.96) translateY(8px); opacity: 0; } }

/* Admin role modal */
.admin-role-modal { border-radius: 22px; }
.admin-modal-error { margin: 16px 22px 0; padding: 12px 14px; border: 1px solid rgba(239,68,68,.35); border-radius: 12px; background: rgba(239,68,68,.08); color: var(--red); font-size: 13px; font-weight: 700; }
.admin-role-fields { border-bottom: 1px solid var(--border); }
.admin-role-permissions { padding: 20px 22px 16px; border-bottom: 1px solid var(--border); }
.admin-role-permissions-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 13px; }
.admin-role-section-title { font-size: 16px; line-height: 1.2; font-weight: 850; color: var(--text); letter-spacing: -.01em; }
.admin-role-section-sub { margin-top: 4px; font-size: 12.5px; line-height: 1.45; color: var(--text-2); }
.admin-permission-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px 14px; max-height: 236px; overflow-y: auto; padding: 1px 3px 3px 1px; align-items: stretch; }
.admin-permission-card { min-height: 54px; display: flex; align-items: center; gap: 12px; margin: 0; padding: 13px 14px; border: 1px solid var(--border); border-radius: 14px; background: var(--surface); box-shadow: var(--shadow-sm); color: var(--text); font-size: 13px; font-weight: 700; cursor: pointer; transition: border-color .16s ease, background .16s ease, box-shadow .16s ease, transform .16s ease; }
.admin-permission-card:hover { border-color: var(--border-strong); background: var(--surface-2); }
.admin-permission-card.selected { border-color: color-mix(in srgb, var(--accent) 42%, var(--border)); background: var(--accent-soft); box-shadow: 0 10px 22px -18px var(--accent); }
.admin-permission-card input { width: 15px; height: 15px; flex: 0 0 auto; accent-color: var(--accent); }
.admin-permission-card .mono { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12.5px; letter-spacing: .01em; }
.admin-permission-add { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px; margin-top: 14px; align-items: center; }
.admin-permission-add input { width: 100%; height: 40px; box-sizing: border-box; border: 1px solid var(--border-strong); border-radius: 10px; background: var(--surface); color: var(--text); padding: 0 12px; font: 600 13px var(--font-ui); outline: none; }
.admin-permission-add input:focus { border-color: var(--accent); box-shadow: var(--ring); }
.admin-role-note { margin-top: 0 !important; }
.admin-action-card.clickable { cursor: pointer; transition: border-color .16s ease, box-shadow .16s ease, transform .16s ease; }
.admin-action-card.clickable:hover,
.admin-action-card.clickable:focus { border-color: color-mix(in srgb, var(--accent) 36%, var(--border)); box-shadow: 0 18px 36px -28px var(--accent); transform: translateY(-1px); outline: none; }
.admin-import-modal { border-radius: 22px; }
.admin-import-fields { border-bottom: 1px solid var(--border); }
.admin-file-drop { display: grid !important; grid-template-columns: 42px minmax(0,1fr); gap: 4px 12px; align-items: center; padding: 14px !important; border: 1px dashed color-mix(in srgb, var(--accent) 34%, var(--border-strong)); border-radius: 14px; background: linear-gradient(135deg, var(--accent-soft), var(--surface)); cursor: pointer; text-transform: none !important; letter-spacing: 0 !important; color: var(--text) !important; }
.admin-file-drop input { position: absolute; width: 1px !important; height: 1px !important; padding: 0 !important; margin: -1px !important; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0 !important; }
.admin-file-icon { grid-row: 1 / span 2; width: 42px; height: 42px; border-radius: 13px; display: grid; place-items: center; background: var(--surface); color: var(--accent); border: 1px solid var(--border); box-shadow: var(--shadow-sm); }
.admin-file-main { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font: 850 14px var(--font-ui); color: var(--text); }
.admin-file-sub { font: 700 11.5px var(--font-ui); color: var(--text-3); }
.admin-import-template { border: 1px solid var(--border); border-radius: 14px; background: var(--surface-2); overflow: hidden; }
