.admin-import-template-head b,
.admin-import-template-head span { display: block; }
.admin-import-template-head b { font: 850 13px var(--font-ui); color: var(--text); }
.admin-import-template-head span { margin-top: 3px; font: 700 11px var(--font-ui); color: var(--text-3); }
.admin-import-template pre { margin: 0; padding: 13px; max-height: 122px; overflow: auto; white-space: pre-wrap; word-break: break-word; color: var(--text-2); font: 700 12px/1.55 var(--font-mono); }
.admin-preview-panel { padding: 18px 22px; border-bottom: 1px solid var(--border); background: linear-gradient(180deg, var(--surface), var(--surface-2)); }
.admin-approval-layout { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(340px, .9fr); gap: 14px; align-items: start; }
.admin-workflow-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); gap: 12px; }
.admin-workflow-card { appearance: none; -webkit-appearance: none; display: grid; grid-template-columns: 40px minmax(0,1fr); gap: 3px 12px; width: 100%; min-height: 112px; padding: 14px; border: 1px solid var(--border); border-radius: 15px; background: var(--surface); color: var(--text); text-align: left; cursor: pointer; box-shadow: var(--shadow-sm); transition: border-color .16s ease, background .16s ease, box-shadow .16s ease, transform .16s ease; }
.admin-workflow-card:hover,
.admin-workflow-card:focus { border-color: color-mix(in srgb, var(--accent) 34%, var(--border)); background: var(--surface-2); outline: none; transform: translateY(-1px); }
.admin-workflow-card.selected { border-color: color-mix(in srgb, var(--accent) 50%, var(--border)); background: var(--accent-soft); box-shadow: 0 16px 30px -26px var(--accent); }
.admin-workflow-icon { grid-row: 1 / span 3; width: 40px; height: 40px; border-radius: 13px; display: grid; place-items: center; background: var(--surface-3); color: var(--accent); }
.admin-workflow-main { min-width: 0; font: 850 14px var(--font-ui); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.admin-workflow-sub { font: 700 11.5px var(--font-ui); color: var(--text-3); }
.admin-workflow-steps { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 5px; }
.admin-workflow-steps span { display: inline-flex; min-height: 22px; align-items: center; padding: 0 8px; border-radius: 999px; background: var(--surface); border: 1px solid var(--border); font: 800 10px var(--font-ui); color: var(--text-2); }
.admin-workflow-detail { display: grid; gap: 14px; }
.admin-workflow-timeline { display: grid; gap: 10px; }
.admin-workflow-step { display: grid; grid-template-columns: 34px minmax(0,1fr); gap: 11px; padding: 12px; border: 1px solid var(--border); border-radius: 13px; background: var(--surface-2); }
.admin-workflow-step-no { width: 34px; height: 34px; border-radius: 12px; display: grid; place-items: center; background: var(--accent); color: #fff; font: 850 13px var(--font-ui); }
.admin-workflow-step b,
.admin-workflow-step span { display: block; }
.admin-workflow-step b { font: 850 13px var(--font-ui); color: var(--text); }
.admin-workflow-step span { margin-top: 4px; font: 700 11.5px var(--font-ui); color: var(--text-3); }
.admin-workflow-controls { display: grid; gap: 9px; }
.admin-workflow-controls > div { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 11px 12px; border: 1px solid var(--border); border-radius: 12px; background: var(--surface); }
.admin-workflow-controls span { font: 800 10.5px var(--font-ui); text-transform: uppercase; letter-spacing: .04em; color: var(--text-3); }
.admin-workflow-controls b { font: 800 12px var(--font-ui); color: var(--text); text-align: right; }

/* ---------- Tabs ---------- */
.tabs { display: flex; align-items: flex-end; gap: 6px; border-bottom: 1px solid var(--border); margin-bottom: 20px; overflow-x: auto; scrollbar-width: thin; }
.tab { appearance: none; -webkit-appearance: none; display: inline-flex; align-items: center; justify-content: center; min-height: 42px; padding: 0 16px; border: 0; border-bottom: 2px solid transparent; border-radius: 10px 10px 0 0; margin: 0 0 -1px; background: transparent; color: var(--text-2); font: 800 13px var(--font-ui); white-space: nowrap; cursor: pointer; transition: color .16s ease, background .16s ease, border-color .16s ease; }
.tab:hover { color: var(--text); background: var(--surface-2); }
.tab.on,
.tab[aria-current="page"] { color: var(--accent); border-bottom-color: var(--accent); background: var(--accent-soft); }
.tab-count { margin-left: 8px; min-width: 22px; height: 22px; padding: 0 7px; border-radius: 999px; display: inline-flex; align-items: center; justify-content: center; background: var(--surface-3); color: var(--text-2); font-size: 11px; font-weight: 850; }

/* Notifications */
.notif-stat-btn { appearance: none; -webkit-appearance: none; border: 0; background: transparent; padding: 0; text-align: left; cursor: pointer; border-radius: var(--r-lg); }
.notif-stat-btn .stat { height: 100%; transition: transform .14s ease, box-shadow .14s ease, border-color .14s ease; }
.notif-stat-btn:hover .stat { transform: translateY(-1px); box-shadow: var(--shadow-md); border-color: color-mix(in srgb, var(--accent) 28%, var(--border)); }
.notif-stat-btn:focus-visible { outline: none; box-shadow: var(--ring); }
.notif-toolbar { display: grid; grid-template-columns: minmax(280px, 1fr) auto; gap: 12px; align-items: center; margin: 0 0 14px; }
.notif-search { min-height: 52px; display: flex; align-items: center; gap: 10px; border: 1px solid var(--border); background: var(--surface); border-radius: 16px; padding: 0 14px; box-shadow: var(--shadow-sm); color: var(--text-3); }
.notif-search:focus-within { border-color: color-mix(in srgb, var(--accent) 45%, var(--border)); box-shadow: var(--ring); }
.notif-search input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; color: var(--text); font: 700 14px var(--font-ui); height: 42px; }
.notif-search input::placeholder { color: var(--text-3); font-weight: 650; }
.notif-clear { width: 30px; height: 30px; border: 0; border-radius: 10px; background: var(--surface-3); color: var(--text-2); display: grid; place-items: center; cursor: pointer; }
.notif-filter-actions { display: flex; align-items: center; justify-content: flex-end; gap: 10px; flex-wrap: wrap; }
.notif-dd { position: relative; min-width: 168px; }
.notif-dd-btn { width: 100%; min-height: 52px; display: inline-flex; align-items: center; justify-content: space-between; gap: 12px; border: 1px solid var(--border); border-radius: 16px; background: var(--surface); color: var(--text); padding: 0 14px 0 16px; font: 850 14px var(--font-ui); cursor: pointer; box-shadow: var(--shadow-sm); }
.notif-dd-btn:hover, .notif-dd-btn:focus-visible { border-color: color-mix(in srgb, var(--accent) 35%, var(--border)); box-shadow: var(--ring); outline: none; }
.notif-dd-scrim { position: fixed; inset: 0; z-index: 44; }
.notif-dd-menu { position: absolute; top: calc(100% + 8px); right: 0; z-index: 45; width: 100%; min-width: 210px; max-height: 280px; overflow-y: auto; background: var(--surface); border: 1px solid var(--border); border-radius: 16px; box-shadow: var(--shadow-lg); padding: 7px; }
.notif-dd-option { width: 100%; min-height: 38px; display: flex; align-items: center; justify-content: space-between; gap: 10px; border: 0; border-radius: 11px; background: transparent; color: var(--text); padding: 0 10px; text-align: left; font: 750 13px var(--font-ui); cursor: pointer; }
.notif-dd-option:hover { background: var(--surface-2); }
.notif-dd-option.selected { color: var(--accent); background: var(--accent-soft); }
.notif-list { overflow: hidden; }
.notif-row { display: grid; grid-template-columns: 42px minmax(0, 1fr) auto; gap: 14px; padding: 16px 18px; border-bottom: 1px solid var(--border); align-items: center; }
.notif-row:last-child { border-bottom: 0; }
.notif-icon { width: 42px; height: 42px; border-radius: 12px; background: var(--surface-3); display: grid; place-items: center; }
.notif-main { min-width: 0; }
.notif-titleline { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 4px; }
.notif-title { font-weight: 850; font-size: 14px; color: var(--text); }
.notif-body { font-size: 12.8px; line-height: 1.45; }
.notif-number { font-size: 11.5px; margin-top: 4px; }
.notif-side { display: grid; gap: 8px; justify-items: end; min-width: 265px; }
.notif-statusline { display: flex; align-items: center; justify-content: flex-end; gap: 8px; min-height: 24px; }
.notif-time { font-size: 11.5px; white-space: nowrap; }
.notif-actions { display: flex; align-items: center; justify-content: flex-end; gap: 8px; flex-wrap: wrap; }
.notif-empty { min-height: 132px; display: grid; place-items: center; gap: 12px; padding: 28px; text-align: center; color: var(--text-3); font-weight: 650; }

@media (max-width: 980px) {
  .notif-toolbar { grid-template-columns: 1fr; }
  .notif-filter-actions { justify-content: flex-start; }
  .notif-dd { flex: 1 1 180px; }
  .notif-row { grid-template-columns: 42px minmax(0, 1fr); align-items: start; }
  .notif-side { grid-column: 1 / -1; justify-items: start; min-width: 0; padding-left: 56px; }
  .notif-statusline, .notif-actions { justify-content: flex-start; }
}

@media (max-width: 620px) {
  .notif-search { min-height: 48px; border-radius: 14px; }
  .notif-filter-actions { display: grid; grid-template-columns: 1fr; width: 100%; }
  .notif-dd { width: 100%; }
  .notif-row { grid-template-columns: 1fr; }
  .notif-icon { width: 38px; height: 38px; }
  .notif-side { padding-left: 0; }
  .notif-actions .btn { flex: 1 1 auto; }
}

/* Approval Center */
.approval-stat-btn { appearance: none; border: 0; background: transparent; padding: 0; text-align: left; border-radius: var(--r-lg); cursor: pointer; }
.approval-stat-btn:focus-visible { outline: none; box-shadow: var(--ring); }
.approval-stat-btn:hover .stat { transform: translateY(-1px); border-color: color-mix(in srgb, var(--accent) 28%, var(--border)); }
.approval-toolbar { position: relative; z-index: 8; display: flex; align-items: center; gap: 12px; margin: 2px 0 18px; }
.approval-search { width: 100%; min-width: 280px; flex: 1 1 360px; height: 48px; box-sizing: border-box; display: flex; align-items: center; gap: 10px; padding: 0 14px; border: 1px solid var(--border); border-radius: 14px; background: var(--surface); box-shadow: var(--shadow-sm); }
.approval-search:focus-within { border-color: var(--accent); box-shadow: var(--ring); }
.approval-search svg { flex: 0 0 auto; color: var(--text-3); }
.approval-search input { flex: 1 1 auto; width: 100%; min-width: 0; height: auto; border: 0; outline: none; background: transparent; color: var(--text); font: 750 14px/1.2 var(--font-ui); }
.approval-filter-actions { display: flex; align-items: center; justify-content: flex-end; gap: 10px; flex: 0 0 auto; flex-wrap: wrap; }
.approval-dd { position: relative; min-width: 170px; }
.approval-dd-btn { appearance: none; -webkit-appearance: none; width: 100%; min-height: 48px; border: 1px solid var(--border); border-radius: 13px; background: var(--surface); color: var(--text); display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 0 13px 0 15px; font: 850 13.5px var(--font-ui); cursor: pointer; box-shadow: var(--shadow-sm); transition: border-color .16s ease, background .16s ease, box-shadow .16s ease; }
.approval-dd-btn:hover { border-color: var(--border-strong); background: var(--surface-2); }
.approval-dd-btn.open,
.approval-dd-btn:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--ring); }
.approval-dd-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.approval-dd-menu { position: absolute; top: calc(100% + 8px); right: 0; min-width: 100%; width: max-content; max-width: 280px; max-height: 280px; overflow: auto; padding: 6px; border: 1px solid var(--border); border-radius: 14px; background: var(--surface); box-shadow: var(--shadow-lg); z-index: 94; }
.approval-dd-option { appearance: none; -webkit-appearance: none; width: 100%; min-height: 38px; border: 0; border-radius: 10px; background: transparent; color: var(--text); display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 0 10px; font: 800 13px var(--font-ui); text-align: left; cursor: pointer; white-space: nowrap; }
.approval-dd-option:hover { background: var(--surface-2); }
.approval-dd-option.selected { background: var(--accent-soft); color: var(--accent); }
.approval-tabs { margin-top: 4px; margin-bottom: 16px; padding-top: 2px; }
.input-like { min-height: 42px; border: 1px solid var(--border); border-radius: 11px; background: var(--surface); color: var(--text); font: 700 13px var(--font-ui); padding: 0 12px; outline: none; }
.input-like:focus { border-color: var(--accent); box-shadow: var(--ring); }
.approval-row-openable { cursor: default; }
.approval-row-openable:hover td { background: color-mix(in srgb, var(--accent) 4%, transparent); }
.approval-request-cell { display: grid; gap: 5px; justify-items: start; }
.approval-request-link { appearance: none; -webkit-appearance: none; border: 0; background: transparent; color: var(--text); padding: 0; margin: 0; font: 900 14px var(--font-ui); cursor: pointer; text-align: left; border-radius: 8px; text-decoration: none; }
.approval-request-link:hover { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.approval-request-link:focus-visible { outline: none; box-shadow: var(--ring); color: var(--accent); }
.approval-request-link:disabled { cursor: not-allowed; color: var(--text-3); text-decoration: none; }
.approval-table { min-width: 980px; }
.approval-table th,
.approval-table td { vertical-align: middle; }
.approval-table td:first-child { min-width: 210px; }
.approval-table td:nth-child(2) { min-width: 180px; }
.approval-table td:last-child { min-width: 250px; }
.approval-decision-modal { width: 560px; max-width: 94vw; }
.approval-decision-modal .modal-body { padding: 18px 22px; display: grid; gap: 10px; }
.approval-decision-modal .label { display: block; margin-bottom: 7px; font-size: 11px; line-height: 1.2; font-weight: 850; color: var(--text-3); letter-spacing: .03em; text-transform: uppercase; }
.approval-decision-modal textarea.input-like { padding: 11px 12px; resize: vertical; line-height: 1.45; }
.form-error { margin-top: 4px; padding: 9px 11px; border-radius: 10px; background: rgba(239,68,68,.08); color: var(--red); font-size: 12px; font-weight: 800; }
@media (max-width: 1100px) {
  .approval-toolbar { align-items: stretch; flex-direction: column; }
  .approval-search { min-width: 0; flex-basis: auto; }
  .approval-filter-actions { width: 100%; justify-content: flex-start; }
  .approval-dd { flex: 1 1 190px; }
}
@media (max-width: 640px) {
  .approval-filter-actions { display: grid; grid-template-columns: 1fr; }
  .approval-dd { min-width: 0; }
  .approval-dd-menu { left: 0; right: auto; width: 100%; max-width: 100%; }
  .approvals-stats.grid { grid-template-columns: 1fr !important; }
}

/* ---------- Account profile ---------- */
.profile-tabs { margin-bottom: 0; }
.profile-section { display: grid; gap: 16px; }
.profile-metrics-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; }
.profile-metric { min-height: 118px; padding: 18px; border: 1px solid var(--border); border-radius: var(--r-lg); background: var(--surface); box-shadow: var(--shadow-sm); }
.profile-metric-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
.profile-metric-ic { width: 36px; height: 36px; border-radius: 12px; display: grid; place-items: center; }
.profile-metric-label { color: var(--text-2); font-size: 12px; font-weight: 800; text-transform: uppercase; letter-spacing: .035em; }
.profile-metric-value { min-width: 0; margin-bottom: 5px; font: 850 18px/1.25 var(--font-display); color: var(--text); letter-spacing: -.025em; overflow-wrap: anywhere; }
.profile-panel-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; align-items: start; }
.profile-info-list { display: grid; gap: 10px; padding: 16px 18px; }
.profile-info-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 56px; padding: 12px 13px; border: 1px solid var(--border); border-radius: 13px; background: var(--surface-2); }
.profile-info-main { min-width: 0; display: grid; gap: 3px; }
.profile-info-main span { color: var(--text); font-size: 13px; font-weight: 850; }
.profile-info-main small { color: var(--text-3); font-size: 11.5px; font-weight: 650; }
.profile-info-row > .mono,
.profile-info-row > .badge { flex: 0 0 auto; max-width: 52%; overflow: hidden; text-overflow: ellipsis; }
.profile-action-list { display: grid; gap: 12px; padding: 16px 18px; }
.profile-action-card { display: grid; grid-template-columns: 42px minmax(0, 1fr) auto; gap: 12px; align-items: center; padding: 13px; border: 1px solid var(--border); border-radius: 14px; background: var(--surface-2); }
.profile-action-icon { width: 42px; height: 42px; border-radius: 13px; display: grid; place-items: center; color: var(--accent); background: var(--accent-soft); }
.profile-action-body { display: grid; gap: 4px; min-width: 0; }
.profile-action-body b { color: var(--text); font-size: 13.5px; font-weight: 850; }
.profile-action-body span { color: var(--text-3); font-size: 11.5px; font-weight: 650; line-height: 1.45; }
.profile-action-control { display: flex; justify-content: flex-end; }
.profile-activity-table .badge { text-transform: capitalize; }
.profile-activity-dot { width: 10px; height: 10px; border-radius: 999px; background: var(--accent); box-shadow: 0 0 0 4px var(--accent-soft); flex: 0 0 10px; }
@media (max-width: 1200px){
  .profile-metrics-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .profile-panel-grid { grid-template-columns: 1fr; }
}
@media (max-width: 720px){
  .profile-metrics-grid { grid-template-columns: 1fr; }
  .profile-info-row { align-items: flex-start; flex-direction: column; gap: 8px; }
  .profile-info-row > .mono,
  .profile-info-row > .badge { max-width: 100%; }
  .profile-action-card { grid-template-columns: 42px minmax(0, 1fr); }
  .profile-action-control { grid-column: 1 / -1; justify-content: flex-start; }
}

/* ---------- Misc utils ---------- */
.row { display: flex; align-items: center; }
.gap-2 { gap: 8px; } .gap-3 { gap: 12px; } .gap-4 { gap: 16px; }
.mt-2{margin-top:8px}.mt-3{margin-top:12px}.mt-4{margin-top:16px}.mt-5{margin-top:20px}.mt-6{margin-top:24px}
.between { justify-content: space-between; }
.muted { color: var(--text-2); }
.faint { color: var(--text-3); }
.center { display: grid; place-items: center; }
.kpi-mini { font-size: 12px; color: var(--text-2); font-weight: 600; }
.divider { height: 1px; background: var(--border); margin: 16px 0; }
.dot-sep::before { content: "·"; margin: 0 7px; color: var(--text-3); }

/* status dot key */
.sdot { width: 8px; height: 8px; border-radius: 99px; display: inline-block; }

/* phone frame for mobile screens */
.phone { width: 320px; height: 660px; border-radius: 42px; background: var(--surface); border: 1px solid var(--border-strong); box-shadow: var(--shadow-lg); padding: 11px; position: relative; flex: 0 0 320px; }
.phone-screen { width: 100%; height: 100%; border-radius: 32px; overflow: hidden; background: var(--bg); position: relative; display: flex; flex-direction: column; }
.phone-notch { position: absolute; top: 18px; left: 50%; transform: translateX(-50%); width: 96px; height: 22px; background: #0a0c11; border-radius: 99px; z-index: 5; }
.phone-status { height: 38px; display: flex; align-items: flex-end; justify-content: space-between; padding: 0 20px 4px; font-size: 11px; font-weight: 800; color: var(--text); }

/* heatmap cells */
.heat { width: 100%; aspect-ratio: 1; border-radius: 6px; display: grid; place-items: center; font-size: 10px; font-weight: 800; }

/* segmented status legend for inventory */
.inv-legend { display: flex; flex-wrap: wrap; gap: 14px; }
.inv-legend .il { display: flex; align-items: center; gap: 7px; font-size: 12px; font-weight: 600; color: var(--text-2); }
.inv-legend .ik { width: 13px; height: 13px; border-radius: 4px; }

/* responsive sidebar collapse on small */
@media (max-width: 940px){
  .sidebar { position: fixed; left: 0; top: 0; transform: translateX(-100%); box-shadow: var(--shadow-lg); }
  .sidebar.collapsed { width: 264px; flex-basis: 264px; }
  .sidebar.collapsed .nav-label, .sidebar.collapsed .nav-badge, .sidebar.collapsed .sb-brand-name, .sidebar.collapsed .sb-brand-sub, .sidebar.collapsed .sb-search span, .sidebar.collapsed .sb-search kbd { display: revert; }
  .sidebar.collapsed .sb-group-label { opacity: 1; height: auto; padding: 14px 10px 6px; }
  .sidebar.collapsed .nav-item { justify-content: flex-start; padding: 0 11px; }
  .sidebar.mobile-open { transform: none; }
}
.sb-scrim { position: fixed; inset: 0; background: rgba(8,10,16,.45); backdrop-filter: blur(2px); z-index: 25; animation: fade .18s; }
[data-theme="dark"] .sb-scrim { background: rgba(0,0,0,.6); }
@media (min-width: 941px){ .sb-scrim { display: none; } }
@media (max-width: 980px){
  .admin-permission-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 700px){
  .scrim { padding: 12px; align-items: start; }
  .modal { width: 100% !important; max-width: 100%; max-height: calc(100vh - 24px); border-radius: 16px; }
  .modal-head { padding: 16px; }
  .modal .form-grid { grid-template-columns: 1fr !important; padding: 16px; gap: 13px; }
  .modal-foot { padding: 12px 16px; flex-wrap: wrap; }
  .modal-foot .btn, .modal-foot button { flex: 1 1 auto; justify-content: center; }
  .admin-role-permissions { padding: 16px; }
  .admin-role-permissions-head { flex-direction: column; gap: 8px; }
  .admin-permission-grid { grid-template-columns: 1fr; max-height: 260px; }
  .admin-permission-add { grid-template-columns: 1fr; }
  .admin-permission-add .btn { width: 100%; justify-content: center; }
  .admin-import-template-head { flex-direction: column; align-items: stretch; }
  .admin-approval-layout { grid-template-columns: 1fr; }
  .admin-workflow-grid { grid-template-columns: 1fr; }
}

/* ---- keyboard focus visibility (a11y) ---- */
:focus { outline: none; }
button:focus-visible, a:focus-visible, input:focus-visible, textarea:focus-visible,
select:focus-visible, [role="button"]:focus-visible, [tabindex]:focus-visible, .nav-item:focus-visible {
  outline: none; box-shadow: var(--ring); border-radius: 9px; position: relative; z-index: 1;
}
.cv-row:focus-visible, .tab:focus-visible, .cf:focus-visible { box-shadow: var(--ring); }

/* ============================================================
   Chat Connect — enterprise messaging module
   ============================================================ */
.chat { display: flex; height: 100%; min-height: 0; background: var(--surface); }
.chat-fullscreen { position: fixed; inset: 0; z-index: 70; width: 100vw; height: 100vh; background: var(--surface); box-shadow: 0 0 0 9999px rgba(15,18,32,.32); }
.chat-fullscreen .chat-main, .chat-fullscreen .msgs { min-height: 0; }

/* presence */
.pres-wrap { position: relative; flex: none; }
.pres-dot { position: absolute; bottom: -1px; right: -1px; width: 11px; height: 11px; border-radius: 99px; border: 2px solid var(--surface); }
.cv-row.active .pres-dot, .chat-head .pres-dot { border-color: var(--surface); }

/* ---- conversation list ---- */
.chat-list-shell { width: 326px; flex: 0 0 326px; display: flex; min-height: 0; position: relative; }
.chat-list-shell.collapsed { display: none; }
.chat-list { width: 326px; flex: 0 0 326px; border-right: 1px solid var(--border); display: flex; flex-direction: column; min-height: 0; background: var(--surface); }
.chat-list-shell .chat-list { width: 100%; flex: 1 1 auto; }
.chat-list-toggle { height: 34px; padding: 0 11px; border-radius: 9px; border: 1px solid var(--border); background: var(--surface); color: var(--text-2); font: 800 12px var(--font-ui); display: inline-flex; align-items: center; gap: 6px; cursor: pointer; white-space: nowrap; }
.chat-list-toggle:hover { border-color: var(--border-strong); color: var(--text); box-shadow: var(--shadow-sm); }
.chat-list-toggle.inside { position: absolute; right: 10px; bottom: 10px; background: var(--surface); box-shadow: var(--shadow-sm); }
.chat-head-tools { display: inline-flex; align-items: center; gap: 6px; margin-left: auto; }
.chat-list-head { padding: 16px 16px 12px; border-bottom: 1px solid var(--border); }
.cl-title { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 13px; }
.cl-title h2 { font-size: 18px; font-weight: 800; letter-spacing: -.03em; display: flex; align-items: center; gap: 9px; }
.cl-title .cl-logo { width: 30px; height: 30px; border-radius: 9px; background: var(--accent-grad); display: grid; place-items: center; color: #fff; box-shadow: 0 5px 13px -4px rgba(79,70,229,.5); }
.cl-search { height: 38px; border-radius: 10px; background: var(--surface-3); border: 1px solid var(--border); display: flex; align-items: center; gap: 8px; padding: 0 11px; color: var(--text-3); }
.cl-search input { border: none; background: none; outline: none; flex: 1; font-family: inherit; font-size: 13px; color: var(--text); }
.chat-filters { display: flex; gap: 5px; padding: 10px 14px 12px; overflow-x: auto; overflow-y: hidden; border-bottom: 1px solid var(--border); scrollbar-width: thin; scrollbar-color: var(--border-strong) transparent; -webkit-overflow-scrolling: touch; }
.chat-filters button { flex: 0 0 auto; white-space: nowrap; }
.chat-filters::-webkit-scrollbar { height: 8px; }
.chat-filters::-webkit-scrollbar-track { background: transparent; }
.chat-filters::-webkit-scrollbar-thumb { background: var(--border-strong); border-radius: 99px; border: 2px solid var(--surface); }
.chat-filters::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.cf { height: 28px; padding: 0 11px; border-radius: 99px; border: 1px solid var(--border); background: var(--surface); font-size: 12px; font-weight: 700; color: var(--text-2); white-space: nowrap; flex: none; display: inline-flex; align-items: center; gap: 5px; }
.cf:hover { border-color: var(--border-strong); }
.cf.on { background: var(--accent-soft); color: var(--accent); border-color: transparent; }
.cf .cf-n { font-size: 10.5px; background: var(--accent); color: #fff; border-radius: 99px; min-width: 16px; height: 16px; padding: 0 4px; display: grid; place-items: center; }

.chat-rows { flex: 1; overflow-y: auto; padding: 8px 8px 16px; min-height: 0; }
.cl-sec { font-size: 10px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; color: var(--text-3); padding: 14px 10px 6px; display: flex; align-items: center; justify-content: space-between; }
.cv-row { display: flex; align-items: center; gap: 11px; padding: 9px 10px; border-radius: 11px; cursor: pointer; position: relative; }
.cv-row:hover { background: var(--surface-3); }
.cv-row.active { background: var(--accent-soft); }
.cv-ic { width: 40px; height: 40px; border-radius: 11px; display: grid; place-items: center; color: #fff; flex: 0 0 40px; }
.cv-main { flex: 1; min-width: 0; }
.cv-top { display: flex; align-items: center; gap: 7px; }
.cv-name { font-weight: 700; font-size: 13.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 1; }
.cv-row.active .cv-name { color: var(--accent); }
.cv-time { font-size: 11px; color: var(--text-3); font-weight: 600; flex: none; }
.cv-row.unread .cv-time { color: var(--accent); }
.cv-prev { display: flex; align-items: center; gap: 6px; margin-top: 2px; }
.cv-prev span { font-size: 12px; color: var(--text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 1; }
.cv-row.unread .cv-prev span { color: var(--text-2); font-weight: 600; }
.cv-unread { font-size: 10.5px; font-weight: 800; background: var(--accent); color: #fff; border-radius: 99px; min-width: 18px; height: 18px; padding: 0 5px; display: grid; place-items: center; flex: none; }
.cv-ment { font-size: 10px; font-weight: 900; background: var(--red); color: #fff; border-radius: 99px; width: 18px; height: 18px; display: grid; place-items: center; flex: none; }
.cv-typebadge { font-size: 9.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .03em; padding: 1px 5px; border-radius: 5px; background: var(--surface-3); color: var(--text-3); flex: none; }

/* ---- main thread ---- */
.chat-main { flex: 1; display: flex; flex-direction: column; min-width: 0; min-height: 0; background: var(--surface-2); }
.chat-head { height: 64px; flex: 0 0 64px; display: flex; align-items: center; gap: 12px; padding: 0 18px; border-bottom: 1px solid var(--border); background: var(--surface); }
.chat-head .ch-ic { width: 40px; height: 40px; border-radius: 11px; display: grid; place-items: center; color: #fff; flex: none; }
.chat-head .ch-name { font-family: var(--font-display); font-weight: 800; font-size: 15.5px; letter-spacing: -.02em; display: flex; align-items: center; gap: 8px; }
.chat-head .ch-sub { font-size: 11.5px; color: var(--text-3); font-weight: 600; margin-top: 1px; display: flex; align-items: center; gap: 6px; }
.ch-actions { display: flex; align-items: center; gap: 4px; margin-left: auto; }
.ch-btn { width: 36px; height: 36px; border-radius: 9px; display: grid; place-items: center; color: var(--text-2); border: 1px solid transparent; }
.ch-btn:hover { background: var(--surface-3); color: var(--text); }
.ch-btn.on { background: var(--accent-soft); color: var(--accent); }

.pin-banner { display: flex; align-items: center; gap: 9px; padding: 9px 18px; background: var(--accent-soft); border-bottom: 1px solid var(--border); font-size: 12.5px; color: var(--text-2); }
.pin-banner b { color: var(--text); font-weight: 700; }

.msgs { flex: 1; overflow-y: auto; padding: 18px 22px 8px; min-height: 0; display: flex; flex-direction: column; gap: 3px; }
.day-sep { display: flex; align-items: center; gap: 12px; margin: 14px 0 10px; color: var(--text-3); font-size: 11px; font-weight: 800; letter-spacing: .04em; text-transform: uppercase; }
.day-sep::before, .day-sep::after { content: ""; flex: 1; height: 1px; background: var(--border); }
.sys-note { text-align: center; font-size: 11.5px; color: var(--text-3); font-weight: 600; padding: 6px 0; font-style: italic; }

.msg-row { display: flex; gap: 11px; padding: 4px 0; position: relative; align-items: flex-start; }
.msg-row.you { flex-direction: row-reverse; }
.msg-body { max-width: min(620px, 74%); display: flex; flex-direction: column; gap: 3px; }
.msg-row.you .msg-body { align-items: flex-end; }
.msg-head { display: flex; align-items: baseline; gap: 8px; }
.msg-name { font-weight: 800; font-size: 12.5px; color: var(--text); }
.msg-role { font-size: 9.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .03em; padding: 1px 6px; border-radius: 5px; }
.msg-time { font-size: 10.5px; color: var(--text-3); font-weight: 600; }
.bubble { background: var(--surface); border: 1px solid var(--border); border-radius: 4px 14px 14px 14px; padding: 9px 13px; font-size: 13.5px; line-height: 1.5; color: var(--text); box-shadow: var(--shadow-sm); }
.msg-row.you .bubble { background: var(--accent); border-color: transparent; color: #fff; border-radius: 14px 4px 14px 14px; }
.bubble .men { color: var(--accent); font-weight: 700; background: var(--accent-soft); padding: 0 4px; border-radius: 4px; }
.msg-row.you .bubble .men { color: #fff; background: rgba(255,255,255,.2); }
.read-tick { display: inline-flex; align-items: center; gap: 3px; font-size: 10.5px; color: rgba(255,255,255,.85); margin-top: 2px; }

/* hover actions */
.msg-actions { position: absolute; top: -10px; display: flex; gap: 2px; background: var(--surface); border: 1px solid var(--border); border-radius: 9px; padding: 3px; box-shadow: var(--shadow-md); opacity: 0; pointer-events: none; transition: .12s; z-index: 4; }
.msg-row:hover .msg-actions,
.msg-row:focus-within .msg-actions,
.msg-actions.show,
.msg-actions:hover { opacity: 1; pointer-events: auto; }
.msg-row.you .msg-actions { right: 52px; }
.msg-row:not(.you) .msg-actions { left: 52px; }
.ma-btn { width: 28px; height: 28px; border-radius: 7px; display: grid; place-items: center; color: var(--text-2); border: none; background: none; }
.ma-btn:hover { background: var(--surface-3); color: var(--text); }
.emoji-pop { position: absolute; top: 22px; display: flex; gap: 2px; background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 5px; box-shadow: var(--shadow-lg); z-index: 6; }
.emoji-pop button { width: 30px; height: 30px; border: none; background: none; border-radius: 7px; font-size: 16px; }
.emoji-pop button:hover { background: var(--surface-3); transform: scale(1.15); }

/* reactions */
.react-row { display: flex; gap: 5px; margin-top: 4px; flex-wrap: wrap; }
.react-chip { display: inline-flex; align-items: center; gap: 4px; height: 23px; padding: 0 7px; border-radius: 99px; background: var(--surface); border: 1px solid var(--border); font-size: 12px; font-weight: 700; color: var(--text-2); }
.react-chip:hover { border-color: var(--border-strong); }
.react-chip.me { background: var(--accent-soft); border-color: transparent; color: var(--accent); }
.react-chip .rn { font-family: var(--font-mono); font-size: 11px; }

.reply-link { display: inline-flex; align-items: center; gap: 7px; margin-top: 5px; font-size: 12px; font-weight: 700; color: var(--accent); padding: 4px 9px 4px 7px; border-radius: 99px; background: var(--surface); border: 1px solid var(--border); align-self: flex-start; }
.reply-link:hover { background: var(--accent-soft); border-color: transparent; }
.reply-link .ravs { display: flex; }
.reply-link .ravs .avatar-sm { margin-right: -7px; border: 2px solid var(--surface); }

/* attachments */
.attach-card { display: flex; align-items: center; gap: 11px; padding: 10px 12px; border-radius: 11px; background: var(--surface); border: 1px solid var(--border); margin-top: 6px; max-width: 320px; }
.msg-row.you .attach-card { background: rgba(255,255,255,.14); border-color: rgba(255,255,255,.2); }
.attach-ic { width: 38px; height: 38px; border-radius: 9px; display: grid; place-items: center; color: #fff; flex: none; }
.attach-name { font-weight: 700; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.attach-sub { font-size: 11px; color: var(--text-3); font-weight: 600; }
.msg-row.you .attach-sub { color: rgba(255,255,255,.8); }
.attach-img { margin-top: 6px; border-radius: 12px; overflow: hidden; border: 1px solid var(--border); max-width: 300px; }
.attach-img .ph { height: 168px; background: linear-gradient(135deg, #1e293b, #334155); display: grid; place-items: center; color: rgba(255,255,255,.7); position: relative; }
.attach-img .cap { display: flex; align-items: center; gap: 8px; padding: 8px 11px; background: var(--surface); font-size: 11.5px; }
.chat-image-preview { max-width: min(420px, 100%); background: var(--surface); box-shadow: var(--shadow-sm); }
.chat-image-frame { display: block; width: 100%; border: 0; padding: 0; background: var(--surface-2); cursor: zoom-in; }
.chat-image-frame img { display: block; width: 100%; max-height: 280px; object-fit: contain; background: var(--surface-2); }
.chat-image-preview .cap { min-width: 0; justify-content: space-between; }
.chat-image-preview .cap > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chat-image-preview .cap .ct-btn { width: 28px; height: 28px; margin-left: 4px; flex: none; }

/* poll / task / decision cards */
.rich-card { margin-top: 6px; border-radius: 13px; border: 1px solid var(--border); background: var(--surface); padding: 14px; max-width: 420px; box-shadow: var(--shadow-sm); }
.rich-head { display: flex; align-items: center; gap: 8px; font-size: 11px; font-weight: 800; letter-spacing: .05em; text-transform: uppercase; color: var(--text-3); margin-bottom: 10px; }
.poll-opt { margin-bottom: 9px; cursor: pointer; }
.poll-opt:last-child { margin-bottom: 0; }
.poll-line { display: flex; align-items: center; justify-content: space-between; margin-bottom: 4px; font-size: 13px; font-weight: 600; }
.poll-track { height: 26px; border-radius: 7px; background: var(--surface-3); overflow: hidden; position: relative; }
.poll-fill { height: 100%; background: var(--accent-soft); border-radius: 7px; transition: width .4s; }
.poll-opt.lead .poll-fill { background: color-mix(in srgb, var(--accent) 26%, transparent); }
.task-card-row { display: flex; align-items: center; gap: 10px; margin-top: 9px; }
.task-meta { display: flex; gap: 7px; flex-wrap: wrap; margin-top: 10px; }

/* typing indicator */
.typing { display: flex; align-items: center; gap: 10px; padding: 6px 0 2px; }
.typing .dots { display: flex; gap: 3px; background: var(--surface); border: 1px solid var(--border); padding: 9px 12px; border-radius: 4px 12px 12px 12px; }
.typing .dots i { width: 6px; height: 6px; border-radius: 99px; background: var(--text-3); animation: typedot 1.2s infinite; }
.typing .dots i:nth-child(2){ animation-delay: .15s; } .typing .dots i:nth-child(3){ animation-delay: .3s; }
@keyframes typedot { 0%,60%,100%{ transform: translateY(0); opacity: .4; } 30%{ transform: translateY(-4px); opacity: 1; } }

/* composer */
.composer { padding: 12px 18px 16px; border-top: 1px solid var(--border); background: var(--surface); }
.composer-box { position: relative; border: 1px solid var(--border-strong); border-radius: 14px; background: var(--surface-2); transition: .15s; }
.composer-box:focus-within { border-color: var(--accent); box-shadow: var(--ring); }
.composer-box textarea { width: 100%; min-height: 58px; border: none; background: none; outline: none; resize: none; font-family: inherit; font-size: 13.5px; color: var(--text); padding: 14px 14px 6px; line-height: 1.5; max-height: 180px; }
.composer-tools { display: flex; align-items: center; gap: 2px; padding: 6px 8px 8px; }
.ct-btn { width: 32px; height: 32px; border-radius: 8px; display: grid; place-items: center; color: var(--text-3); border: none; background: none; }
.ct-btn:hover, .ct-btn.on { background: var(--surface-3); color: var(--text); }
.send-btn { margin-left: auto; width: 36px; height: 36px; border-radius: 10px; background: var(--accent); color: #fff; display: grid; place-items: center; border: none; box-shadow: 0 4px 12px -3px rgba(79,70,229,.5); }
.send-btn:hover { background: var(--accent-press); }
.send-btn:disabled { opacity: .4; box-shadow: none; }
.chat-selected-files { display: flex; flex-wrap: wrap; gap: 8px; padding: 8px 10px 0; }
.chat-file-pill { display: inline-flex; align-items: center; gap: 6px; max-width: 260px; padding: 7px 10px; border: 1px solid var(--border); border-radius: 999px; background: var(--surface); color: var(--text-2); font-size: 12px; font-weight: 800; }
.chat-file-pill button { border: 0; background: transparent; color: var(--text-3); font-size: 16px; line-height: 1; cursor: pointer; }
.chat-recording-note { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin: 8px 10px 0; padding: 9px 10px; border: 1px solid rgba(220,47,58,.22); border-radius: 14px; background: rgba(220,47,58,.08); color: var(--red); font-size: 12px; font-weight: 800; }
.chat-mic-notice { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin: 8px 10px 0; padding: 10px 11px; border: 1px solid rgba(245,158,11,.28); border-radius: 14px; background: rgba(245,158,11,.09); color: var(--orange); font-size: 12px; font-weight: 800; line-height: 1.35; }
.chat-mic-notice span { flex: 1; min-width: 220px; }
.chat-attachments { display: grid; gap: 8px; margin-top: 8px; }
.composer-note { display: flex; align-items: center; gap: 7px; padding: 14px; border-radius: 12px; background: var(--surface-3); color: var(--text-3); font-size: 12.5px; font-weight: 600; justify-content: center; }
.chat-recipient-strip { display: flex; align-items: center; justify-content: flex-end; gap: 10px; margin-bottom: 10px; }
.chat-sendto-label { display: inline-flex; align-items: center; gap: 8px; font-size: 11px; font-weight: 800; color: var(--text-2); position: relative; }
.chat-recipient-picker { position: relative; min-width: 250px; }
.chat-recipient-picker.compact { min-width: 290px; }
.chat-recipient-btn { width: 100%; height: 36px; border: 1px solid var(--border); border-radius: 10px; background: var(--surface); color: var(--text); font: 800 12px var(--font-ui); display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 0 10px; cursor: pointer; }
.chat-recipient-btn span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chat-recipient-btn:hover, .chat-recipient-btn:focus-visible { border-color: var(--accent); box-shadow: var(--ring); outline: 0; }
.chat-recipient-menu { position: absolute; right: 0; top: calc(100% + 6px); width: min(360px, 82vw); z-index: 110; border: 1px solid var(--border); border-radius: 14px; background: var(--surface); box-shadow: var(--shadow-lg); overflow: hidden; }
.chat-recipient-menu .people-search-picker { margin-top: 0; border: 0; box-shadow: none; border-radius: 14px; }
.chat-recipient-menu .people-search-list { max-height: 260px; }
.chat-forward-targets { display: grid; gap: 10px; }
.chat-forward-target-list { display: grid; gap: 8px; max-height: 220px; overflow: auto; padding: 4px; border: 1px solid var(--border); border-radius: 14px; background: var(--surface-2); }
.chat-forward-target { width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 12px; text-align: left; border: 1px solid transparent; border-radius: 12px; padding: 10px 12px; background: transparent; color: var(--text); cursor: pointer; }
.chat-forward-target:hover, .chat-forward-target:focus-visible, .chat-forward-target.on { border-color: var(--accent); background: var(--accent-soft); outline: none; }
.chat-forward-target span { min-width: 0; display: grid; gap: 2px; }
.chat-forward-target strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; font-weight: 850; }
.chat-forward-target small, .chat-forward-empty { color: var(--text-3); font-size: 12px; font-weight: 750; }
.chat-forward-empty { padding: 14px; text-align: center; }
.chat-type-badge { margin-left: 8px; height: 22px; padding: 0 8px; font-size: 10.5px; text-transform: capitalize; }
.chat-mention-menu { position: absolute; left: 10px; bottom: 50px; width: min(380px, calc(100% - 20px)); z-index: 125; border: 1px solid var(--border); border-radius: 16px; background: var(--surface); box-shadow: var(--shadow-lg); overflow: hidden; }
.chat-mention-search { height: 44px; display: flex; align-items: center; gap: 8px; padding: 0 10px; border-bottom: 1px solid var(--border); color: var(--text-3); }
.chat-mention-search input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; color: var(--text); font: 750 13px var(--font-ui); }
.chat-mention-list { max-height: 260px; overflow-y: auto; padding: 7px; }
.chat-mention-option { width: 100%; min-height: 52px; border: 0; border-radius: 12px; background: transparent; display: flex; align-items: center; gap: 10px; padding: 8px 10px; color: var(--text); text-align: left; cursor: pointer; }
.chat-mention-option:hover, .chat-mention-option:focus-visible { background: var(--accent-soft); outline: 0; }
.chat-mention-main { flex: 1; min-width: 0; display: grid; gap: 2px; }
.chat-mention-main strong, .chat-mention-main small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chat-mention-main strong { font-size: 13px; font-weight: 850; }
.chat-mention-main small { color: var(--text-3); font-size: 11.5px; font-weight: 700; }
.chat-mention-empty { padding: 22px; color: var(--text-3); text-align: center; font-size: 12.5px; font-weight: 750; }
.chat-composer-emoji { position: absolute; left: 10px; bottom: 50px; z-index: 126; width: min(320px, calc(100% - 20px)); display: grid; grid-template-columns: repeat(8, 1fr); gap: 4px; padding: 9px; border: 1px solid var(--border); border-radius: 16px; background: var(--surface); box-shadow: var(--shadow-lg); }
.chat-composer-emoji button { height: 34px; border: 0; border-radius: 10px; background: transparent; font-size: 18px; cursor: pointer; }
.chat-composer-emoji button:hover,
.chat-composer-emoji button:focus-visible { background: var(--surface-3); transform: scale(1.08); outline: 0; }

/* ---- Chat Connect modal forms ---- */
.chat-modal-scrim { position: fixed; inset: 0; z-index: 1200; display: grid; place-items: center; padding: 18px; background: rgba(15,23,42,.52); }
.chat-modal { width: min(760px, 94vw); max-height: min(92vh, 860px); display: flex; flex-direction: column; overflow: hidden; background: var(--surface); border: 1px solid var(--border); border-radius: 20px; box-shadow: var(--shadow-lg); }
.chat-modal-head { flex: none; display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; padding: 22px 24px 14px; border-bottom: 1px solid var(--border); }
.chat-modal-head h2 { margin: 0; font: 850 22px/1.15 var(--font-display); letter-spacing: -.03em; color: var(--text); }
.chat-modal-head p { margin: 6px 0 0; color: var(--text-2); font-size: 13px; line-height: 1.45; }
.chat-modal-body { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 18px 24px; display: grid; gap: 14px; }
.chat-modal-foot { flex: none; display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 16px 24px; border-top: 1px solid var(--border); background: color-mix(in srgb, var(--surface) 94%, transparent); backdrop-filter: blur(10px); }
.chat-form-label { display: grid; gap: 7px; margin: 0; color: var(--text-2); font-size: 12.5px; line-height: 1.2; font-weight: 850; }
.chat-field { width: 100%; min-width: 0; box-sizing: border-box; border: 1px solid var(--border-strong); border-radius: 13px; background: var(--surface); color: var(--text); font: 750 14px var(--font-ui); outline: 0; transition: border-color .16s ease, box-shadow .16s ease, background .16s ease; }
select.chat-field { height: 50px; padding: 0 15px; cursor: pointer; }
input.chat-field { height: 54px; padding: 0 15px; }
textarea.chat-field { min-height: 122px; padding: 14px 15px; line-height: 1.5; resize: vertical; }
.chat-field:focus { border-color: var(--accent); box-shadow: var(--ring); }
.chat-field:disabled { opacity: .7; cursor: not-allowed; background: var(--surface-2); }
.chat-alert { display: flex; align-items: flex-start; gap: 9px; padding: 12px 14px; border: 1px solid var(--border); border-radius: 14px; background: var(--surface-2); color: var(--text-2); font-size: 12.5px; font-weight: 750; line-height: 1.45; }
.chat-alert.compact { font-style: italic; }
.chat-alert.error { border-color: rgba(239,68,68,.32); background: rgba(239,68,68,.08); color: var(--red); }
.chat-modal .people-search-picker { margin-top: 0; border-radius: 14px; }
.chat-modal .people-search-list { max-height: 292px; }
.chat-modal .people-search-option { min-height: 52px; }
.chat-modal-card.chat-poll-modal { width: min(760px, 94vw); max-height: calc(100vh - 32px); display: flex; flex-direction: column; overflow: hidden; border-radius: 22px; }
.chat-modal-card.chat-poll-modal .chat-modal-head { padding: 20px 24px 14px; }
.chat-modal-card.chat-poll-modal .chat-modal-body { padding: 18px 24px; }
.chat-modal-card.chat-poll-modal .chat-modal-foot { padding: 14px 24px; }
.chat-poll-body { grid-template-columns: 1fr; align-items: start; gap: 16px; }
.chat-poll-form { display: grid; gap: 14px; min-width: 0; }
.chat-field-hint { justify-self: end; color: var(--text-3); font-size: 11px; font-weight: 750; }
.chat-poll-options { display: grid; gap: 9px; }
.chat-poll-option-row { display: grid; grid-template-columns: 34px minmax(0, 1fr) 34px; align-items: center; gap: 8px; }
.chat-poll-option-index { width: 30px; height: 30px; border-radius: 10px; display: grid; place-items: center; background: var(--accent-soft); color: var(--accent); font-size: 12px; font-weight: 900; }
.chat-add-option { width: max-content; margin-top: 10px; }
.chat-toggle-row { display: flex; align-items: flex-start; gap: 10px; padding: 12px 13px; border: 1px solid var(--border); border-radius: 14px; background: var(--surface-2); color: var(--text-2); }
.chat-toggle-row input { margin-top: 3px; }
.chat-toggle-row span { display: grid; gap: 3px; }
.chat-toggle-row strong { color: var(--text); font-size: 13px; }
.chat-toggle-row small { color: var(--text-3); font-size: 12px; font-weight: 650; }
.chat-poll-preview { border: 1px solid var(--border); border-radius: 18px; background: var(--surface-2); padding: 16px; box-shadow: var(--shadow-sm); }
.chat-poll-preview h3 { margin: 0 0 6px; font-size: 16px; line-height: 1.35; letter-spacing: -.02em; }
.chat-poll-preview-options { display: grid; gap: 9px; margin-top: 14px; }
.chat-poll-preview-option { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 38px; padding: 0 12px; border: 1px solid var(--border); border-radius: 12px; background: var(--surface); color: var(--text-2); font-size: 12.5px; font-weight: 800; }

@media (min-width: 1280px) and (min-height: 760px) {
  .chat-modal-card.chat-poll-modal { width: min(980px, 94vw); }
  .chat-poll-body { grid-template-columns: minmax(0, 1.05fr) minmax(300px, .95fr); }
  .chat-poll-preview { position: sticky; top: 0; }
}

/* ---- details panel ---- */
.details { width: 320px; flex: 0 0 320px; border-left: 1px solid var(--border); display: flex; flex-direction: column; min-height: 0; background: var(--surface); }
.details-tabs { display: flex; padding: 0 12px; border-bottom: 1px solid var(--border); flex: none; }
.details-tabs .dt { flex: 1; padding: 13px 0; text-align: center; font-size: 12px; font-weight: 700; color: var(--text-3); border-bottom: 2px solid transparent; margin-bottom: -1px; }
.details-tabs .dt.on { color: var(--accent); border-color: var(--accent); }
.details-body { flex: 1; overflow-y: auto; min-height: 0; }
.det-hero { padding: 24px 18px; text-align: center; border-bottom: 1px solid var(--border); }
.det-hero .dh-ic { width: 66px; height: 66px; border-radius: 18px; display: grid; place-items: center; color: #fff; margin: 0 auto 12px; }
.det-sec { padding: 16px 18px; border-bottom: 1px solid var(--border); }
.det-label { font-size: 10px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; color: var(--text-3); margin-bottom: 9px; }
.member-row { display: flex; align-items: center; gap: 11px; padding: 8px 18px; }
.member-row:hover { background: var(--surface-2); }
.file-row { display: flex; align-items: center; gap: 11px; padding: 10px 18px; border-bottom: 1px solid var(--border); }
.file-row:hover { background: var(--surface-2); }
.det-pin { padding: 13px 18px; border-bottom: 1px solid var(--border); display: flex; gap: 10px; }
.det-pin .pic { color: var(--accent); flex: none; margin-top: 1px; }

@media (max-width: 1280px){ .details { display: none; } }
@media (max-width: 1000px){
  .chat-list-shell { width: 280px; flex-basis: 280px; }
  .chat-list { width: 280px; flex-basis: 280px; }
}
@media (max-width: 760px){
  .chat-head { height: auto; min-height: 64px; padding: 10px 12px; flex-wrap: wrap; }
  .chat-head-tools { order: 3; width: 100%; margin-left: 0; }
  .ch-actions { flex-wrap: wrap; }
  .chat-list-shell { position: absolute; inset: 0 auto 0 0; width: min(326px, 88vw); z-index: 60; box-shadow: var(--shadow-lg); }
  .chat-list-shell.collapsed { display: none; }
  .chat-modal-scrim { padding: 10px; align-items: stretch; }
  .chat-modal { width: 100%; max-height: calc(100vh - 20px); border-radius: 18px; }
  .chat-modal-head, .chat-modal-body, .chat-modal-foot { padding-left: 16px; padding-right: 16px; }
  .chat-modal-foot { align-items: stretch; flex-direction: column; }
  .chat-modal-foot .row { width: 100%; }
  .chat-modal-foot .btn { flex: 1 1 0; justify-content: center; }
  .chat-poll-body { grid-template-columns: 1fr; }
  .chat-modal-card.chat-poll-modal { width: 100%; max-height: calc(100vh - 20px); }
  .chat-mention-menu { left: 8px; right: 8px; width: auto; }
  .chat-recipient-strip { justify-content: stretch; }
  .chat-sendto-label, .chat-recipient-picker, .chat-recipient-picker.compact { width: 100%; min-width: 0; }
}

/* ============================================================
   Mailbox module
   ============================================================ */
.mbx { display: flex; height: 100%; min-height: 0; background: var(--surface); position: relative; }
.mbx-fullscreen { position: fixed; inset: 0; z-index: 70; width: 100vw; height: 100vh; background: var(--surface); box-shadow: 0 0 0 9999px rgba(15,18,32,.32); }
.mbx-fullscreen .mbx-read,
.mbx-fullscreen .mbx-read-main,
.mbx-fullscreen .mbx-list,
.mbx-fullscreen .mbx-rows { min-height: 0; }
.mbx-fullscreen .mbx-list { width: 460px; flex-basis: 460px; }

/* ---- folder rail ---- */
.mbx-rail { width: 234px; flex: 0 0 234px; border-right: 1px solid var(--border); display: flex; flex-direction: column; min-height: 0; background: var(--surface); }
.mbx-rail-head { padding: 14px 14px 10px; }
.mbx-compose { width: 100%; height: 44px; border-radius: 12px; border: none; background: var(--accent); color: #fff; font-weight: 800; font-size: 14px; font-family: inherit;
  display: flex; align-items: center; justify-content: center; gap: 9px; box-shadow: 0 6px 16px -4px rgba(79,70,229,.5); transition: .14s; }
.mbx-compose:hover { background: var(--accent-press); }
.mbx-compose svg { width: 18px; height: 18px; }

.mbx-acct-wrap { position: relative; margin: 4px 8px 8px; }
.mbx-acct { width: 100%; min-height: 54px; padding: 9px 10px; border-radius: 12px; border: 1px solid var(--border); background: var(--surface-2); display: flex; align-items: center; gap: 10px; cursor: pointer; position: relative; box-sizing: border-box; }
.mbx-acct:hover { background: var(--surface-2); box-shadow: inset 0 0 0 1px var(--border); }
.mbx-acct-dot { width: 8px; height: 8px; border-radius: 99px; flex: none; }
.mbx-acct-main { flex: 1; min-width: 0; }
.mbx-acct-email { font-weight: 700; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mbx-acct-sub { font-size: 10.5px; color: var(--text-3); font-weight: 600; }
.mbx-acct-menu { top: calc(100% + 6px); left: 0; right: 0; min-width: 0; width: auto; padding: 7px; border-radius: 14px; }
.mbx-acct-menu .mbx-mitem { height: 42px; padding: 0 10px; border-radius: 10px; gap: 10px; }
.mbx-acct-menu .mbx-msep { margin: 7px 2px; }
.mbx-menu-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.mbx-folders { flex: 1; overflow-y: auto; padding: 6px 8px 14px; min-height: 0; }
.mbx-fold { display: flex; align-items: center; gap: 11px; height: 38px; padding: 0 11px; border-radius: 10px; color: var(--text-2); font-weight: 600; font-size: 13px; cursor: pointer; position: relative; margin-bottom: 2px; }
.mbx-fold:hover { background: var(--surface-3); color: var(--text); }
.mbx-fold.on { background: var(--accent-soft); color: var(--accent); }
.mbx-fold.on::before { content: ""; position: absolute; left: -8px; top: 50%; transform: translateY(-50%); width: 3px; height: 18px; border-radius: 0 3px 3px 0; background: var(--accent); }
.mbx-fold svg { width: 17px; height: 17px; flex: none; opacity: .82; }
.mbx-fold .mbx-fcount { margin-left: auto; font-size: 11px; font-weight: 800; color: var(--text-3); }
.mbx-fold.on .mbx-fcount { color: var(--accent); }
.mbx-fold .mbx-unread { margin-left: auto; font-size: 10.5px; font-weight: 800; background: var(--accent); color: #fff; border-radius: 99px; min-width: 18px; height: 18px; padding: 0 5px; display: grid; place-items: center; }
.mbx-rail-sec { font-size: 10px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; color: var(--text-3); padding: 14px 11px 6px; display: flex; align-items: center; justify-content: space-between; }
.mbx-lbl-dot { width: 9px; height: 9px; border-radius: 3px; flex: none; }

.mbx-sync { padding: 10px 14px; border-top: 1px solid var(--border); display: flex; align-items: center; gap: 9px; font-size: 11.5px; color: var(--text-3); font-weight: 600; }
.mbx-sync .sync-ic { color: var(--green); display: grid; place-items: center; }
.mbx-sync .sync-ic.spin svg { animation: mbxspin .8s linear infinite; }
@keyframes mbxspin { to { transform: rotate(360deg); } }
.mbx-sync button { margin-left: auto; border: none; background: none; color: var(--accent); font-weight: 700; font-size: 11.5px; font-family: inherit; padding: 3px 6px; border-radius: 6px; }
.mbx-sync button:hover { background: var(--accent-soft); }

/* ---- email list ---- */
.mbx-list { width: 420px; flex: 0 0 420px; border-right: 1px solid var(--border); display: flex; flex-direction: column; min-height: 0; background: var(--surface); }
.mbx-list.wide { flex: 1; }
.mbx-ltop { padding: 14px 16px 12px; border-bottom: 1px solid var(--border); }
.mbx-ltitle { display: flex; align-items: center; gap: 10px; margin-bottom: 13px; min-width: 0; }
.mbx-ltitle { flex-wrap: wrap; }
.mbx-ltitle h2 { font-size: 18px; font-weight: 800; letter-spacing: -.03em; flex: 1; min-width: 0; text-transform: capitalize; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mbx-ltitle .mbx-abtn { flex: none; }
.mbx-lsearch { display: flex; align-items: center; gap: 9px; height: 42px; padding: 0 12px; border-radius: 12px; background: var(--surface-3); border: 1px solid transparent; color: var(--text-3); transition: .14s; box-sizing: border-box; }
.mbx-lsearch:focus-within { background: var(--surface); border-color: var(--accent); box-shadow: var(--ring); }
.mbx-lsearch input { border: none; background: none; outline: none; flex: 1; color: var(--text); font-family: inherit; font-size: 13px; }
.mbx-lfilters { display: flex; gap: 7px; margin-top: 12px; flex-wrap: wrap; align-items: center; }
.mbx-lfilters .mbx-fchip { flex: 0 0 auto; }
.mbx-fchip { height: 32px; padding: 0 11px; border-radius: 10px; border: 1px solid var(--border); background: var(--surface); font-size: 11.5px; font-weight: 700; color: var(--text-2); display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.mbx-fchip:hover { border-color: var(--border-strong); }
.mbx-fchip.on { background: var(--accent-soft); color: var(--accent); border-color: transparent; }
.mbx-fchip svg { width: 13px; height: 13px; }
.mbx-fullscreen-toggle { height: 32px; padding: 0 10px; border-radius: 9px; border: 1px solid var(--border); background: var(--surface); color: var(--text-2); font-weight: 800; font-size: 11.5px; font-family: inherit; display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; }
.mbx-fullscreen-toggle:hover { color: var(--accent); border-color: var(--accent); background: var(--accent-soft); }
.mbx-fullscreen-toggle svg { width: 15px; height: 15px; }

.mbx-rows { flex: 1; overflow-y: auto; min-height: 0; }
.mbx-row { display: flex; gap: 11px; padding: 12px 14px; border-bottom: 1px solid var(--border); cursor: pointer; position: relative; align-items: flex-start; }
.mbx-row:hover { background: var(--surface-2); }
.mbx-row.active { background: var(--accent-soft); }
.mbx-row.active::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: var(--accent); }
.mbx-row.unread { background: color-mix(in srgb, var(--accent-soft) 45%, var(--surface)); }
.mbx-row.unread.active { background: var(--accent-soft); }
.mbx-rcheck { flex: none; display: flex; flex-direction: column; align-items: center; gap: 8px; padding-top: 2px; }
.mbx-cb { width: 16px; height: 16px; border-radius: 5px; border: 1.5px solid var(--border-strong); background: var(--surface); display: grid; place-items: center; cursor: pointer; color: transparent; }
.mbx-cb.on { background: var(--accent); border-color: var(--accent); color: #fff; }
.mbx-cb svg { width: 11px; height: 11px; }
.mbx-star { color: var(--text-3); display: grid; place-items: center; cursor: pointer; background: none; border: none; padding: 0; }
.mbx-star:hover { color: var(--orange); }
.mbx-star.on { color: var(--orange); }
.mbx-star.on svg { fill: var(--orange); }
.mbx-ravatar { flex: none; }
.mbx-rmain { flex: 1; min-width: 0; }
.mbx-rtop { display: flex; align-items: center; gap: 7px; }
.mbx-rname { font-weight: 700; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; flex: 1; color: var(--text); }
.mbx-row.unread .mbx-rname { font-weight: 800; }
.mbx-rtime { font-size: 11px; color: var(--text-3); font-weight: 600; flex: none; }
.mbx-row.unread .mbx-rtime { color: var(--accent); }
.mbx-rsubj { font-size: 12.5px; color: var(--text); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-weight: 500; }
.mbx-row.unread .mbx-rsubj { font-weight: 700; }
.mbx-rsnip { font-size: 12px; color: var(--text-3); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mbx-rmeta { display: flex; align-items: center; gap: 6px; margin-top: 7px; flex-wrap: wrap; }
.mbx-chip { font-size: 10px; font-weight: 800; letter-spacing: .02em; padding: 2px 7px; border-radius: 6px; display: inline-flex; align-items: center; gap: 4px; }
.mbx-chip .ic { width: 7px; height: 7px; border-radius: 99px; }
.mbx-rattach { color: var(--text-3); display: inline-flex; align-items: center; }
.mbx-rlinked { display: inline-flex; align-items: center; gap: 3px; font-size: 10px; font-weight: 800; color: var(--green); background: var(--green-soft); padding: 2px 6px; border-radius: 6px; }
.mbx-unread-dot { position: absolute; left: 5px; top: 18px; width: 7px; height: 7px; border-radius: 99px; background: var(--accent); }

/* bulk action bar */
.mbx-bulk { display: flex; align-items: center; gap: 7px; padding: 9px 14px; border-bottom: 1px solid var(--border); background: var(--accent-soft); flex-wrap: wrap; }
.mbx-bulk .bcount { font-weight: 800; font-size: 12.5px; color: var(--accent); margin-right: 4px; }
.mbx-bbtn { height: 30px; padding: 0 9px; border-radius: 8px; border: 1px solid transparent; background: var(--surface); color: var(--text-2); font-weight: 700; font-size: 12px; font-family: inherit; display: inline-flex; align-items: center; gap: 5px; }
.mbx-bbtn:hover { color: var(--text); box-shadow: inset 0 0 0 1px var(--border-strong); }
.mbx-bbtn svg { width: 14px; height: 14px; }

/* ---- reading pane ---- */
.mbx-read { flex: 1; display: flex; min-width: 0; min-height: 0; background: var(--surface-2); }
.mbx-read-main { flex: 1; display: flex; flex-direction: column; min-width: 0; min-height: 0; }
.mbx-read-top { padding: 16px 22px 14px; border-bottom: 1px solid var(--border); background: var(--surface); flex: none; }
.mbx-read-actions { display: flex; align-items: center; gap: 6px; margin-bottom: 14px; flex-wrap: wrap; }
.mbx-abtn { width: 34px; height: 34px; border-radius: 9px; border: 1px solid var(--border); background: var(--surface); display: grid; place-items: center; color: var(--text-2); transition: .12s; }
.mbx-abtn:hover { color: var(--text); border-color: var(--border-strong); background: var(--surface-2); }
.mbx-abtn.on { color: var(--orange); border-color: var(--orange); }
.mbx-abtn.on svg { fill: var(--orange); }
.mbx-abtn svg { width: 16px; height: 16px; }
.mbx-asep { width: 1px; height: 22px; background: var(--border); margin: 0 3px; }
.mbx-read-subj { font-size: 19px; font-weight: 800; letter-spacing: -.02em; line-height: 1.3; }
.mbx-read-subjrow { display: flex; align-items: flex-start; gap: 10px; }
.mbx-read-body { flex: 1; overflow-y: auto; padding: 8px 22px 30px; min-height: 0; }

.mbx-msg { background: var(--surface); border: 1px solid var(--border); border-radius: 14px; margin-top: 16px; box-shadow: var(--shadow-sm); overflow: hidden; }
.mbx-msg-head { display: flex; align-items: center; gap: 11px; padding: 14px 18px; cursor: pointer; }
.mbx-msg-head:hover { background: var(--surface-2); }
.mbx-msg-who { flex: 1; min-width: 0; }
.mbx-msg-from { font-weight: 700; font-size: 13.5px; }
.mbx-msg-to { font-size: 11.5px; color: var(--text-3); margin-top: 1px; }
.mbx-msg-time { font-size: 11.5px; color: var(--text-3); font-weight: 600; flex: none; }
.mbx-msg-body { padding: 4px 18px 20px; font-size: 14px; line-height: 1.62; color: var(--text); }
.mbx-msg-body p { margin: 0 0 12px; }
.mbx-msg-body b { font-weight: 700; }
.mbx-collapsed .mbx-msg-body { display: none; }
.mbx-msg-snip { flex: 1; font-size: 12.5px; color: var(--text-3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.mbx-atts { display: flex; flex-wrap: wrap; gap: 9px; padding: 0 18px 18px; }
.mbx-att { display: flex; align-items: center; gap: 9px; padding: 8px 11px; border: 1px solid var(--border); border-radius: 10px; background: var(--surface-2); min-width: 180px; cursor: pointer; }
.mbx-att:hover { border-color: var(--border-strong); background: var(--surface); }
.mbx-att-ic { width: 32px; height: 32px; border-radius: 8px; display: grid; place-items: center; color: #fff; font-size: 9px; font-weight: 800; flex: none; }
