.mbx-reply-btn:hover { background: var(--surface-2); border-color: var(--text-3); }
.mbx-reply-btn svg { width: 15px; height: 15px; }

/* CRM context panel */
.mbx-crm { width: 274px; flex: 0 0 274px; border-left: 1px solid var(--border); background: var(--surface); overflow-y: auto; min-height: 0; }
.mbx-crm-sec { padding: 16px 18px; border-bottom: 1px solid var(--border); }
.mbx-crm-label { font-size: 10px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; color: var(--text-3); margin-bottom: 12px; }
.mbx-crm-contact { display: flex; align-items: center; gap: 12px; }
.mbx-crm-name { font-weight: 800; font-size: 15px; }
.mbx-crm-meta { font-size: 12px; color: var(--text-3); font-weight: 600; margin-top: 1px; }
.mbx-crm-kv { display: flex; align-items: center; gap: 8px; padding: 7px 0; font-size: 12.5px; }
