@media (max-width: 1340px){ .mbx-crm { display: none; } }
@media (max-width: 1280px){ .mbx-list { width: 380px; flex-basis: 380px; } }
@media (max-width: 1140px){ .mbx-list { width: 340px; flex-basis: 340px; } }
@media (max-width: 980px){ .mbx-rail { width: 210px; flex-basis: 210px; } }
@media (max-width: 860px){ .mbx-fullscreen .mbx-list { width: 100%; flex-basis: auto; } }
@media (max-width: 1020px) {
  .tm-body.pad > .grid { grid-template-columns: 1fr !important; }
  .cal-primarybar, .tm-compactbar { align-items: flex-start; }
