}

/* ---- compose dock ---- */
.mbx-compose-dock { position: absolute; bottom: 0; right: 22px; width: 560px; max-width: calc(100% - 44px); background: var(--surface); border: 1px solid var(--border-strong); border-radius: 14px 14px 0 0; box-shadow: var(--shadow-lg); z-index: 60; display: flex; flex-direction: column; max-height: calc(100% - 16px); opacity: 1; animation: mbxDockIn .2s cubic-bezier(.2,.7,.3,1); }
.mbx-compose-dock.full { position: fixed; inset: 70px 40px 0 40px; width: auto; max-width: none; max-height: none; border-radius: 16px 16px 0 0; }
.mbx-compose-dock.min { height: 46px; }
@keyframes mbxDockIn { from { transform: translateY(30px); } to { transform: translateY(0); } }
.mbx-cdock-head { height: 46px; flex: none; background: var(--text); color: #fff; border-radius: 13px 13px 0 0; display: flex; align-items: center; gap: 8px; padding: 0 14px; cursor: pointer; }
[data-theme="dark"] .mbx-cdock-head { background: var(--surface-3); }
.mbx-cdock-head .ct { font-weight: 700; font-size: 13px; flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mbx-cdock-head button { width: 26px; height: 26px; border-radius: 7px; border: none; background: transparent; color: inherit; display: grid; place-items: center; }
.mbx-cdock-head button:hover { background: rgba(255,255,255,.16); }
.mbx-cdock-head button svg { width: 15px; height: 15px; }
[data-theme="dark"] .mbx-cdock-head { color: var(--text); }
.mbx-cdock-body { flex: 1; display: flex; flex-direction: column; min-height: 0; overflow: hidden; }
.mbx-cfield { display: flex; align-items: center; gap: 8px; padding: 0 16px; border-bottom: 1px solid var(--border); min-height: 42px; }
.mbx-cfield .lbl { font-size: 12px; color: var(--text-3); font-weight: 700; width: 42px; flex: none; }
.mbx-cfield input { flex: 1; border: none; background: none; outline: none; font-family: inherit; font-size: 13px; color: var(--text); padding: 10px 0; }
.mbx-cfield .ccbcc { display: flex; gap: 8px; }
.mbx-cfield .ccbcc button { border: none; background: none; color: var(--text-3); font-weight: 700; font-size: 12px; font-family: inherit; padding: 4px; }
.mbx-cfield .ccbcc button:hover { color: var(--accent); }
.mbx-pill { display: inline-flex; align-items: center; gap: 6px; background: var(--surface-3); border-radius: 7px; padding: 4px 8px; font-size: 12px; font-weight: 700; }
.mbx-pill button { border: none; background: none; color: var(--text-3); display: grid; place-items: center; padding: 0; }
.mbx-cbody { flex: 1; overflow-y: auto; padding: 14px 16px; font-size: 14px; line-height: 1.6; color: var(--text); outline: none; min-height: 120px; }
.mbx-cbody:empty::before { content: attr(data-ph); color: var(--text-3); }
.mbx-cbody p { margin: 0 0 10px; }
.mbx-ctoolbar { display: flex; align-items: center; gap: 3px; padding: 7px 12px; border-top: 1px solid var(--border); flex-wrap: wrap; }
.mbx-tbtn { width: 32px; height: 32px; border-radius: 8px; border: none; background: transparent; color: var(--text-2); display: grid; place-items: center; }
.mbx-tbtn:hover { background: var(--surface-3); color: var(--text); }
.mbx-tbtn svg { width: 16px; height: 16px; }
.mbx-tbtn.fmt-on { background: var(--accent-soft); color: var(--accent); }
.mbx-cfoot { display: flex; align-items: center; gap: 8px; padding: 10px 14px; border-top: 1px solid var(--border); }
.mbx-send { height: 38px; padding: 0 18px; border-radius: 9px; border: none; background: var(--accent); color: #fff; font-weight: 800; font-size: 13px; font-family: inherit; display: inline-flex; align-items: center; gap: 8px; box-shadow: 0 4px 12px -3px rgba(79,70,229,.45); }
.mbx-send:hover { background: var(--accent-press); }
.mbx-send-split { border-left: 1px solid rgba(255,255,255,.25); padding-left: 8px; margin-left: 2px; display: grid; place-items: center; }
.mbx-catt { display: flex; align-items: center; gap: 9px; padding: 8px 11px; margin: 0 14px 10px; border: 1px solid var(--border); border-radius: 10px; background: var(--surface-2); }

/* attachment chip in compose */
.mbx-catt-list { padding: 0 2px; display: flex; flex-direction: column; gap: 7px; }

/* dropdown menu (shared) */
.mbx-menu { position: absolute; background: var(--surface); border: 1px solid var(--border); border-radius: 12px; box-shadow: var(--shadow-lg); padding: 6px; z-index: 70; min-width: 200px; }
.mbx-mitem { display: flex; align-items: center; gap: 10px; height: 36px; padding: 0 11px; border-radius: 8px; font-size: 13px; font-weight: 600; color: var(--text); cursor: pointer; }
.mbx-mitem:hover { background: var(--surface-3); }
.mbx-mitem svg { width: 16px; height: 16px; color: var(--text-3); flex: none; }
.mbx-mitem.danger { color: var(--red); } .mbx-mitem.danger svg { color: var(--red); }
.mbx-msep { height: 1px; background: var(--border); margin: 5px 0; }

/* connect & settings pages reuse .page; a couple extras */
.mbx-conn-card { padding: 26px; border-radius: var(--r-lg); border: 1px solid var(--border); background: var(--surface); box-shadow: var(--shadow-sm); }
.mbx-conn-logo { width: 52px; height: 52px; border-radius: 14px; display: grid; place-items: center; margin-bottom: 16px; }
.mbx-form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 16px; }
.mbx-field label { display: block; font-size: 12px; font-weight: 700; color: var(--text-2); margin-bottom: 6px; }
.mbx-input { width: 100%; height: 40px; border-radius: 9px; border: 1px solid var(--border-strong); background: var(--surface); padding: 0 12px; font-family: inherit; font-size: 13px; color: var(--text); outline: none; box-sizing: border-box; }
.mbx-input:focus { border-color: var(--accent); box-shadow: var(--ring); }
.mbx-select { width: 100%; height: 40px; border-radius: 9px; border: 1px solid var(--border-strong); background: var(--surface); padding: 0 10px; font-family: inherit; font-size: 13px; color: var(--text); outline: none; box-sizing: border-box; }
.mbx-toggle { width: 40px; height: 23px; border-radius: 99px; background: var(--border-strong); border: none; position: relative; cursor: pointer; flex: none; transition: .16s; }
.mbx-toggle.on { background: var(--accent); }
.mbx-toggle::after { content: ""; position: absolute; top: 2px; left: 2px; width: 19px; height: 19px; border-radius: 99px; background: #fff; transition: .16s; box-shadow: 0 1px 3px rgba(0,0,0,.25); }
.mbx-toggle.on::after { left: 19px; }
.mbx-setrow { display: flex; align-items: center; gap: 14px; padding: 14px 0; border-bottom: 1px solid var(--border); }
.mbx-setrow:last-child { border-bottom: none; }
.mbx-setrow .st-main { flex: 1; }
.mbx-setrow .st-name { font-weight: 700; font-size: 13.5px; }
.mbx-setrow .st-sub { font-size: 12px; color: var(--text-3); margin-top: 2px; }

.mbx-banner { display: flex; align-items: flex-start; gap: 11px; padding: 11px 16px; border-radius: 11px; font-size: 12.5px; font-weight: 600; margin-bottom: 14px; line-height: 1.45; min-width: 0; }
.mbx-banner.warn { background: var(--orange-soft); color: var(--orange); }
.mbx-banner.info { background: var(--accent-soft); color: var(--accent); }
.mbx-banner svg { flex: none; }

/* mobile: collapse to single pane */
.mbx-back { display: none; }
@media (max-width: 860px){
  .mbx-rail { display: none; }
  .mbx-list { width: 100%; flex: 1; }
  .mbx-list.has-sel { display: none; }
  .mbx-read { position: absolute; inset: 0; z-index: 40; }
  .mbx-back { display: grid; }
}

/* ============================================================
   Task Management module
   ============================================================ */
.tm { display: flex; height: 100%; min-height: 0; background: var(--surface); position: relative; }
.tm-fullscreen { position: fixed; inset: 0; z-index: 70; width: 100vw; height: 100vh; background: var(--surface); box-shadow: 0 0 0 9999px rgba(15,18,32,.32); }
.tm-fullscreen .tm-main, .tm-fullscreen .tm-body { min-height: 0; }

/* ---- sub-nav rail ---- */
.tm-rail { width: 230px; flex: 0 0 230px; border-right: 1px solid var(--border); display: flex; flex-direction: column; min-height: 0; background: var(--surface); }
.tm-rail.workspace-hidden { display: none; }
.tm-rail-head { padding: 14px 14px 8px; }
.tm-new { width: 100%; height: 42px; border-radius: 11px; border: none; background: var(--accent); color: #fff; font-weight: 800; font-size: 13.5px; font-family: inherit;
  display: flex; align-items: center; justify-content: center; gap: 8px; box-shadow: 0 6px 16px -5px rgba(79,70,229,.55); transition: .14s; }
.tm-new:hover { background: var(--accent-press); }
.tm-new svg { width: 17px; height: 17px; }
.tm-new.compact { width: auto; height: 36px; padding: 0 15px; border-radius: 9px; font-size: 13px; flex: none; }
.tm-nav { flex: 1; overflow-y: auto; padding: 4px 8px 16px; min-height: 0; }
.tm-nav-sec { font-size: 10px; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; color: var(--text-3); padding: 14px 11px 5px; }
.tm-nav-item { display: flex; align-items: center; gap: 10px; height: 34px; padding: 0 11px; border-radius: 9px; color: var(--text-2); font-weight: 600; font-size: 12.5px; cursor: pointer; position: relative; margin-bottom: 1px; }
.tm-nav-item:hover { background: var(--surface-3); color: var(--text); }
.tm-nav-item.on { background: var(--accent-soft); color: var(--accent); font-weight: 700; }
.tm-nav-item.on::before { content: ""; position: absolute; left: -8px; top: 50%; transform: translateY(-50%); width: 3px; height: 17px; border-radius: 0 3px 3px 0; background: var(--accent); }
.tm-nav-item svg { width: 16px; height: 16px; flex: none; opacity: .85; }
.tm-nav-item .tm-ncount { margin-left: auto; font-size: 11px; font-weight: 800; color: var(--text-3); }
.tm-nav-item.on .tm-ncount { color: var(--accent); }
.tm-nav-item .tm-ndot { margin-left: auto; font-size: 10.5px; font-weight: 800; background: var(--red); color: #fff; border-radius: 99px; min-width: 18px; height: 18px; padding: 0 5px; display: grid; place-items: center; }

/* ---- main work area ---- */
.tm-main { flex: 1; display: flex; flex-direction: column; min-width: 0; min-height: 0; background: var(--surface-2); }
.tm-compactbar { display: flex; align-items: center; gap: 9px; padding: 12px 24px; border-bottom: 1px solid var(--border); flex: none; flex-wrap: wrap; background: var(--surface); }
.tm-compact-title { min-width: 150px; display: flex; flex-direction: column; gap: 2px; }
.tm-compact-title b { font-size: 16px; font-weight: 800; letter-spacing: -.02em; color: var(--text); }
.tm-compact-title span { font-size: 11.5px; font-weight: 700; color: var(--text-3); }
.tm-selected-chip { height: 28px; border: none; border-radius: 99px; padding: 0 10px; background: var(--accent-soft); color: var(--accent); font: 800 11.5px var(--font-ui); cursor: pointer; }
.tm-options-panel { display: flex; align-items: center; gap: 9px; padding: 10px 24px; border-bottom: 1px solid var(--border); flex: none; flex-wrap: wrap; background: var(--surface); }
.tm-options-panel.closed { display: none; }
.tm-topbar { padding: 14px 24px 0; flex: none; }
.tm-toolbar { display: flex; align-items: center; gap: 9px; padding: 12px 24px; border-bottom: 1px solid var(--border); flex: none; flex-wrap: wrap; background: var(--surface); }
.tm-body { flex: 1; overflow-y: auto; min-height: 0; }
.tm-body.pad { padding: 22px 24px 60px; }

/* view switcher segmented */
.tm-viewseg { display: inline-flex; background: var(--surface-3); border-radius: 9px; padding: 3px; gap: 2px; }
.tm-viewseg button { height: 30px; padding: 0 12px; border: none; background: none; border-radius: 7px; font-family: inherit; font-size: 12.5px; font-weight: 700; color: var(--text-3); display: inline-flex; align-items: center; gap: 6px; }
.tm-viewseg button svg { width: 15px; height: 15px; }
.tm-viewseg button.on { background: var(--surface); color: var(--text); box-shadow: var(--shadow-sm); }

.tm-search { display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 11px; border-radius: 9px; background: var(--surface-3); border: 1px solid transparent; color: var(--text-3); min-width: 200px; }
.tm-search:focus-within { background: var(--surface); border-color: var(--accent); box-shadow: var(--ring); }
.tm-search input { border: none; background: none; outline: none; flex: 1; color: var(--text); font-family: inherit; font-size: 13px; min-width: 0; }
.tm-tbtn { height: 36px; padding: 0 12px; border-radius: 9px; border: 1px solid var(--border); background: var(--surface); font-weight: 700; font-size: 12.5px; color: var(--text-2); font-family: inherit; display: inline-flex; align-items: center; gap: 6px; }
.tm-tbtn:hover { border-color: var(--border-strong); color: var(--text); }
.tm-tbtn.on { background: var(--accent-soft); color: var(--accent); border-color: transparent; }
.tm-tbtn svg { width: 15px; height: 15px; }
.tm-iconbtn { width: 36px; height: 36px; border-radius: 9px; border: 1px solid var(--border); background: var(--surface); display: grid; place-items: center; color: var(--text-2); }
.tm-iconbtn:hover { border-color: var(--border-strong); color: var(--text); }
.tm-iconbtn svg { width: 16px; height: 16px; }

/* priority + status pills */
.tm-pri { display: inline-flex; align-items: center; gap: 5px; font-size: 11px; font-weight: 800; padding: 2px 8px; border-radius: 6px; white-space: nowrap; }
.tm-pri .pdot { width: 7px; height: 7px; border-radius: 99px; }
.tm-flame { display: inline-flex; align-items: center; }

/* ============ KANBAN ============ */
.tm-kanban { display: flex; gap: 14px; padding: 18px 24px 40px; min-height: 100%; align-items: stretch; }
.tm-col { width: 296px; flex: 0 0 296px; background: var(--surface); border: 1px solid var(--border); border-radius: 14px; display: flex; flex-direction: column; height: 100%; max-height: calc(100vh - 180px); overflow: hidden; }
.tm-col-head { display: flex; align-items: center; gap: 8px; padding: 12px 13px; border-bottom: 1px solid var(--border); position: sticky; top: 0; flex-shrink: 0; background: var(--surface); }
.tm-col-dot { width: 9px; height: 9px; border-radius: 99px; flex: none; }
.tm-col-title { font-weight: 800; font-size: 13px; }
.tm-col-count { font-size: 11px; font-weight: 800; color: var(--text-3); background: var(--surface-3); border-radius: 99px; padding: 1px 8px; }
.tm-col-add { margin-left: auto; width: 26px; height: 26px; border-radius: 7px; border: none; background: none; color: var(--text-3); display: grid; place-items: center; }
.tm-col-add:hover { background: var(--surface-3); color: var(--accent); }
.tm-col-body { padding: 10px; display: flex; flex-direction: column; gap: 10px; overflow-y: auto; overscroll-behavior: contain; min-height: 60px; flex: 1 1 auto; max-height: calc(100vh - 235px); scrollbar-width: thin; }
.tm-col-body::-webkit-scrollbar { width: 5px; }
.tm-col-body::-webkit-scrollbar-track { background: transparent; }
.tm-col-body::-webkit-scrollbar-thumb { background: rgba(100, 116, 139, 0.35); border-radius: 4px; }
.tm-col-body::-webkit-scrollbar-thumb:hover { background: rgba(100, 116, 139, 0.6); }
.tm-col-body.dragover { background: var(--accent-soft); border-radius: 0 0 13px 13px; outline: 2px dashed var(--accent); outline-offset: -6px; }

.tm-card { flex: 0 0 auto !important; flex-shrink: 0 !important; min-height: max-content !important; background: var(--surface-2); border: 1px solid var(--border); border-radius: 11px; padding: 12px; cursor: grab; transition: box-shadow .12s, transform .12s; position: relative; }
.tm-card:hover { box-shadow: var(--shadow-sm); border-color: var(--border-strong); }
.tm-card.dragging { opacity: .4; }
.tm-card-top { display: flex; align-items: center; gap: 7px; margin-bottom: 8px; }
.tm-card-id { font-size: 10.5px; font-weight: 800; color: var(--text-3); font-family: var(--font-ui); }
.tm-card-title { font-size: 13px; font-weight: 700; line-height: 1.4; color: var(--text); margin-bottom: 9px; }
.tm-card-tags { display: flex; flex-wrap: wrap; gap: 5px; margin-bottom: 9px; }
.tm-tag { font-size: 10px; font-weight: 700; padding: 2px 7px; border-radius: 6px; background: var(--surface-3); color: var(--text-2); }
.tm-card-foot { display: flex; align-items: center; gap: 8px; }
.tm-card-meta { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; font-weight: 700; color: var(--text-3); }
.tm-card-meta svg { width: 13px; height: 13px; }
.tm-card-meta.due-over { color: var(--red); }
.tm-card-meta.due-today { color: var(--orange); }
.tm-avstack { display: flex; align-items: center; }
.tm-avstack > * { margin-left: -7px; border: 2px solid var(--surface-2); border-radius: 99px; }
.tm-avstack > *:first-child { margin-left: 0; }
.tm-subprog { display: inline-flex; align-items: center; gap: 5px; font-size: 11px; font-weight: 700; color: var(--text-3); }
.tm-miniring { --p: 0; width: 16px; height: 16px; border-radius: 99px; background: conic-gradient(var(--green) calc(var(--p) * 1%), var(--surface-3) 0); position: relative; }
.tm-miniring::after { content: ""; position: absolute; inset: 3px; border-radius: 99px; background: var(--surface-2); }

/* ============ LIST / GRID ============ */
.tm-grid-wrap { padding: 0; }
.tm-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.tm-table thead th { position: sticky; top: 0; background: var(--surface); z-index: 2; text-align: left; font-size: 11px; font-weight: 800; letter-spacing: .03em; text-transform: uppercase; color: var(--text-3); padding: 11px 14px; border-bottom: 1px solid var(--border); white-space: nowrap; cursor: pointer; user-select: none; }
.tm-table thead th:hover { color: var(--text-2); }
.tm-table thead th .th-sort { display: inline-flex; align-items: center; gap: 5px; }
.tm-table tbody tr { border-bottom: 1px solid var(--border); cursor: pointer; }
.tm-table tbody tr:hover { background: var(--surface); }
.tm-table tbody tr.sel { background: var(--accent-soft); }
.tm-table td { padding: 11px 14px; vertical-align: middle; }
.tm-td-title { font-weight: 700; color: var(--text); display: flex; align-items: center; gap: 8px; }
.tm-td-title .sub { font-size: 11px; color: var(--text-3); font-weight: 600; }
.tm-cb { width: 16px; height: 16px; border-radius: 5px; border: 1.5px solid var(--border-strong); background: var(--surface); display: grid; place-items: center; cursor: pointer; color: transparent; flex: none; }
.tm-cb.on { background: var(--accent); border-color: var(--accent); color: #fff; }
.tm-cb svg { width: 11px; height: 11px; }
.tm-statbtn { min-height: 34px; display: inline-flex; align-items: center; gap: 7px; cursor: pointer; border: 1px solid var(--border); background: var(--surface-2); border-radius: 10px; padding: 4px 9px; font-family: inherit; color: var(--text); box-shadow: inset 0 1px 0 rgba(255,255,255,.35); }
.tm-statbtn:hover:not(:disabled) { border-color: var(--accent); box-shadow: var(--ring); }
.tm-statbtn:disabled { cursor: default; opacity: .78; }
.tm-statbtn.readonly { background: var(--surface); }

.tm-bulk { display: flex; align-items: center; gap: 8px; padding: 9px 24px; background: var(--accent-soft); border-bottom: 1px solid var(--border); flex-wrap: wrap; }
.tm-bulk .bc { font-weight: 800; font-size: 12.5px; color: var(--accent); margin-right: 4px; }
.tm-bbtn { height: 30px; padding: 0 10px; border-radius: 8px; border: 1px solid transparent; background: var(--surface); color: var(--text-2); font-weight: 700; font-size: 12px; font-family: inherit; display: inline-flex; align-items: center; gap: 5px; }
.tm-bbtn:hover { color: var(--text); box-shadow: inset 0 0 0 1px var(--border-strong); }
.tm-bbtn svg { width: 14px; height: 14px; }

/* ============ CALENDAR ============ */
.tm-cal { padding: 18px 24px 40px; }
.tm-cal-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 1px; background: var(--border); border: 1px solid var(--border); border-radius: 12px; overflow: hidden; }
.tm-cal-dow { background: var(--surface); padding: 9px 12px; font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .04em; color: var(--text-3); }
.tm-cal-cell { background: var(--surface); min-height: 116px; padding: 8px; display: flex; flex-direction: column; gap: 5px; }
.tm-cal-cell.dim { background: var(--surface-2); }
.tm-cal-date { font-size: 12px; font-weight: 700; color: var(--text-2); display: flex; align-items: center; justify-content: space-between; }
.tm-cal-cell.today .tm-cal-date span { background: var(--accent); color: #fff; width: 22px; height: 22px; border-radius: 99px; display: grid; place-items: center; }
.tm-cal-task { font-size: 11px; font-weight: 700; padding: 3px 7px; border-radius: 6px; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; cursor: pointer; }

/* ============ DASHBOARD ============ */
.tm-dash-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 14px; }
.tm-mini { display: flex; flex-direction: column; gap: 4px; }
.tm-workload-row { display: flex; align-items: center; gap: 12px; padding: 9px 0; }
.tm-workload-row .wl-name { width: 130px; flex: none; display: flex; align-items: center; gap: 9px; font-size: 12.5px; font-weight: 600; }
.tm-wl-bar { flex: 1; height: 22px; border-radius: 7px; background: var(--surface-3); overflow: hidden; display: flex; }
.tm-wl-seg { height: 100%; }
.tm-act-row { display: flex; gap: 11px; padding: 11px 0; border-bottom: 1px solid var(--border); }
.tm-act-row:last-child { border-bottom: none; }
.tm-act-ic { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; flex: none; }

/* ============ DETAIL DRAWER ============ */
.tm-drawer-scrim { position: fixed; inset: 0; background: rgba(15,18,32,.42); z-index: 80; display: flex; justify-content: flex-end; animation: tmFade .16s; }
@keyframes tmFade { from { opacity: 0; } }
.tm-drawer { width: 760px; max-width: 96vw; background: var(--surface); height: 100%; display: flex; flex-direction: column; box-shadow: -16px 0 48px -16px rgba(0,0,0,.4); animation: tmSlide .22s cubic-bezier(.2,.7,.3,1); }
@keyframes tmSlide { from { transform: translateX(40px); } }
.tm-dr-head { padding: 16px 22px; border-bottom: 1px solid var(--border); flex: none; }
.tm-dr-crumb { display: flex; align-items: center; gap: 8px; margin-bottom: 12px; }
.tm-dr-id { font-size: 11.5px; font-weight: 800; color: var(--text-3); font-family: var(--font-ui); }
.tm-dr-actions { display: flex; align-items: center; gap: 6px; margin-left: auto; }
.tm-dr-title { font-size: 21px; font-weight: 800; letter-spacing: -.02em; line-height: 1.25; border: 1px solid transparent; border-radius: 8px; padding: 3px 6px; margin: -3px -6px; }
.tm-dr-title:focus { outline: none; border-color: var(--accent); box-shadow: var(--ring); background: var(--surface); }
.tm-dr-title.readonly { cursor: default; color: var(--text); }
.tm-dr-statusbar { display: flex; align-items: center; gap: 10px; margin-top: 13px; flex-wrap: wrap; }
.tm-dr-body { flex: 1; overflow-y: auto; min-height: 0; display: flex; }
.tm-dr-main { flex: 1; min-width: 0; padding: 20px 22px 40px; border-right: 1px solid var(--border); }
.tm-dr-side { width: 244px; flex: 0 0 244px; padding: 18px 18px 40px; background: var(--surface-2); overflow-y: auto; }
.tm-dr-tabs { display: flex; gap: 3px; border-bottom: 1px solid var(--border); margin-bottom: 18px; }
.tm-dr-tab { padding: 9px 13px; font-size: 13px; font-weight: 700; color: var(--text-3); border: 0; border-bottom: 2px solid transparent; margin-bottom: -1px; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; background: transparent; border-radius: 9px 9px 0 0; font-family: inherit; }
.tm-dr-tab:hover { color: var(--text-2); }
.tm-dr-tab.on { color: var(--accent); border-bottom-color: var(--accent); }
.tm-dr-tab:focus-visible { outline: none; box-shadow: var(--ring); }
.tm-dr-tab .cnt { font-size: 10.5px; font-weight: 800; background: var(--surface-3); border-radius: 99px; padding: 0 6px; min-width: 17px; text-align: center; }

.tm-sec-label { font-size: 10.5px; font-weight: 800; letter-spacing: .07em; text-transform: uppercase; color: var(--text-3); margin-bottom: 11px; }
.tm-desc { font-size: 13.5px; line-height: 1.65; color: var(--text); }
.tm-desc p { margin: 0 0 10px; }
.tm-detail-stack { display: flex; flex-direction: column; gap: 14px; }
.tm-detail-card { border: 1px solid var(--border); border-radius: 15px; background: var(--surface); box-shadow: var(--shadow-sm); overflow: visible; }
.tm-detail-card-head { display: flex; align-items: center; gap: 9px; padding: 13px 14px; border-bottom: 1px solid var(--border); color: var(--text-2); }
.tm-detail-card-head h3 { margin: 0; color: var(--text); font-size: 13.5px; font-weight: 800; }
.tm-detail-card-body { padding: 14px; }
.tm-empty-panel { min-height: 78px; border: 1px dashed var(--border-strong); border-radius: 13px; background: var(--surface-2); display: flex; align-items: center; gap: 12px; padding: 14px; color: var(--text-3); }
.tm-empty-ic { width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center; background: var(--surface-3); color: var(--text-2); flex: none; }
.tm-empty-panel b { display: block; color: var(--text); font-size: 13px; margin-bottom: 2px; }
.tm-empty-panel span { display: block; font-size: 12px; line-height: 1.45; }
.tm-dependency-list { display: flex; flex-direction: column; gap: 8px; }
.tm-dep-add { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px; align-items: center; margin-top: 12px; }
.tm-dep-picker { position: relative; min-width: 0; }
.tm-dep-select { width: 100%; min-height: 40px; border-radius: 11px; border: 1px solid var(--border-strong); background: var(--surface); padding: 0 12px; display: flex; align-items: center; justify-content: space-between; gap: 10px; font-family: inherit; font-size: 13px; font-weight: 700; color: var(--text); text-align: left; }
.tm-dep-select span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tm-dep-select:hover:not(:disabled), .tm-dep-select:focus-visible { border-color: var(--accent); box-shadow: var(--ring); outline: none; }
.tm-dep-select:disabled { color: var(--text-3); background: var(--surface-2); cursor: not-allowed; }
.tm-dep-menu { top: 46px; left: 0; right: 0; min-width: 100%; max-height: 260px; }
.tm-dep-option { width: 100%; }
.tm-dep-option-id { font: 800 11px var(--font-ui); color: var(--accent); background: var(--accent-soft); border-radius: 999px; padding: 3px 7px; }
.tm-dep-option-title { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
@media (max-width: 760px) {
  .tm-drawer { width: 100vw; max-width: 100vw; }
  .tm-dr-head { padding: 14px 16px; }
  .tm-dr-body { display: block; overflow-y: auto; }
  .tm-dr-main { border-right: 0; padding: 16px 16px 24px; }
  .tm-dr-side { width: auto; flex-basis: auto; padding: 16px; border-top: 1px solid var(--border); }
  .tm-dr-tabs { overflow-x: auto; scrollbar-width: thin; }
  .tm-dr-tab { white-space: nowrap; }
  .tm-dep-add { grid-template-columns: 1fr; }
}

/* subtasks */
.tm-sub-row { display: flex; align-items: center; gap: 10px; padding: 9px 10px; border: 1px solid var(--border); border-radius: 10px; margin-bottom: 7px; background: var(--surface); }
.tm-sub-row:hover { border-color: var(--border-strong); }
.tm-sub-check { width: 19px; height: 19px; border-radius: 99px; border: 2px solid var(--border-strong); display: grid; place-items: center; cursor: pointer; color: transparent; flex: none; }
.tm-sub-check.on { background: var(--green); border-color: var(--green); color: #fff; }
.tm-sub-check svg { width: 11px; height: 11px; }
.tm-sub-title { flex: 1; font-size: 13px; font-weight: 600; }
.tm-sub-title.done { text-decoration: line-through; color: var(--text-3); }
.tm-addline { display: flex; align-items: center; gap: 9px; padding: 9px 11px; border: 1.5px dashed var(--border-strong); border-radius: 10px; color: var(--text-3); font-weight: 700; font-size: 12.5px; cursor: pointer; width: 100%; background: none; font-family: inherit; }
.tm-addline:hover { border-color: var(--accent); color: var(--accent); }
.tm-addline svg { width: 15px; height: 15px; }
.tm-addrow { display: flex; gap: 8px; }
.tm-addrow input { flex: 1; height: 38px; border-radius: 9px; border: 1px solid var(--border-strong); background: var(--surface); padding: 0 11px; font-family: inherit; font-size: 13px; color: var(--text); outline: none; }
.tm-addrow input:focus { border-color: var(--accent); box-shadow: var(--ring); }

/* checklist progress */
.tm-prog-head { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; }
.tm-prog-track { flex: 1; height: 8px; border-radius: 99px; background: var(--surface-3); overflow: hidden; }
.tm-prog-fill { height: 100%; background: var(--green); border-radius: 99px; transition: width .3s; }
.tm-chk-row { display: flex; align-items: center; gap: 10px; padding: 7px 0; }
.tm-chk-box { width: 17px; height: 17px; border-radius: 5px; border: 2px solid var(--border-strong); display: grid; place-items: center; cursor: pointer; color: transparent; flex: none; }
.tm-chk-box.on { background: var(--accent); border-color: var(--accent); color: #fff; }
.tm-chk-box svg { width: 10px; height: 10px; }
.tm-chk-text { font-size: 13px; }
.tm-chk-text.done { text-decoration: line-through; color: var(--text-3); }

/* comments */
.tm-cmt { display: flex; gap: 11px; margin-bottom: 16px; }
.tm-cmt-body { flex: 1; min-width: 0; }
.tm-cmt-head { display: flex; align-items: center; gap: 8px; margin-bottom: 4px; }
.tm-cmt-who { font-weight: 700; font-size: 13px; }
.tm-cmt-time { font-size: 11px; color: var(--text-3); font-weight: 600; }
.tm-cmt-text { font-size: 13px; line-height: 1.55; color: var(--text); }
.tm-cmt-text .mention { color: var(--accent); font-weight: 700; background: var(--accent-soft); border-radius: 4px; padding: 0 3px; }
.tm-cmt-box { display: flex; gap: 10px; align-items: flex-start; margin-top: 8px; position: sticky; bottom: 0; }
.tm-cmt-input { flex: 1; border: 1px solid var(--border-strong); border-radius: 11px; background: var(--surface); padding: 10px 12px; font-family: inherit; font-size: 13px; color: var(--text); outline: none; resize: none; min-height: 40px; line-height: 1.5; }
.tm-cmt-input:focus { border-color: var(--accent); box-shadow: var(--ring); }

/* activity timeline */
.tm-tl { position: relative; padding-left: 8px; }
.tm-tl-row { display: flex; gap: 12px; padding-bottom: 18px; position: relative; }
.tm-tl-row::before { content: ""; position: absolute; left: 13px; top: 28px; bottom: -4px; width: 2px; background: var(--border); }
.tm-tl-row:last-child::before { display: none; }
.tm-tl-ic { width: 28px; height: 28px; border-radius: 99px; display: grid; place-items: center; flex: none; background: var(--surface-3); color: var(--text-2); z-index: 1; }
.tm-tl-ic svg { width: 14px; height: 14px; }
.tm-tl-text { font-size: 12.5px; line-height: 1.5; padding-top: 4px; }
.tm-tl-text b { font-weight: 700; }
.tm-tl-time { font-size: 11px; color: var(--text-3); font-weight: 600; margin-top: 2px; }

/* time tracking */
.tm-timer { display: flex; align-items: center; gap: 12px; padding: 14px 16px; border: 1px solid var(--border); border-radius: 12px; background: var(--surface-2); margin-bottom: 16px; }
.tm-timer-display { font-family: var(--font-display); font-weight: 800; font-size: 26px; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
.tm-timer-btn { width: 40px; height: 40px; border-radius: 11px; border: none; display: grid; place-items: center; color: #fff; }
.tm-timer-btn svg { width: 18px; height: 18px; }
.tm-tl-log-row { display: flex; align-items: center; gap: 10px; padding: 9px 0; border-bottom: 1px solid var(--border); font-size: 12.5px; }

/* side meta */
.tm-meta-row { padding: 11px 0; border-bottom: 1px solid var(--border); }
.tm-meta-row:last-child { border-bottom: none; }
.tm-meta-k { font-size: 11px; font-weight: 700; color: var(--text-3); margin-bottom: 6px; display: flex; align-items: center; gap: 6px; }
.tm-meta-v { font-size: 13px; font-weight: 600; }
.tm-assignee-add { width: 26px; height: 26px; border-radius: 99px; border: 1.5px dashed var(--border-strong); display: grid; place-items: center; color: var(--text-3); background: none; }
.tm-assignee-add:hover { border-color: var(--accent); color: var(--accent); }
.tm-assignee-add svg { width: 13px; height: 13px; }
.tm-watchbtn { width: 100%; height: 36px; border-radius: 9px; border: 1px solid var(--border-strong); background: var(--surface); font-weight: 700; font-size: 12.5px; font-family: inherit; color: var(--text-2); display: flex; align-items: center; justify-content: center; gap: 7px; }
.tm-watchbtn:hover { border-color: var(--accent); color: var(--accent); }
.tm-watchbtn.on { background: var(--accent-soft); color: var(--accent); border-color: transparent; }
.tm-watchbtn svg { width: 15px; height: 15px; }

/* ============ MODALS (create / transfer) ============ */
.tm-modal-scrim { position: fixed; inset: 0; background: rgba(15,18,32,.5); z-index: 90; display: grid; place-items: center; padding: 24px; animation: tmFade .16s; }
.tm-modal { width: 680px; max-width: 100%; height: min(860px, 92vh); max-height: 92vh; background: var(--surface); border-radius: 18px; box-shadow: var(--shadow-lg); display: flex; flex-direction: column; overflow: hidden; animation: tmSlide .2s cubic-bezier(.2,.7,.3,1); }
.tm-modal > form { display: flex; flex: 1 1 auto; flex-direction: column; min-height: 0; overflow: hidden; }
.tm-modal.sm { width: 480px; }
.tm-modal-head { display: flex; align-items: center; gap: 12px; padding: 18px 22px; border-bottom: 1px solid var(--border); flex: none; }
.tm-modal-head h2 { font-size: 17px; font-weight: 800; flex: 1; }
.tm-modal-body { flex: 1 1 auto; min-height: 0; padding: 20px 22px 28px; overflow-x: hidden; overflow-y: auto; overscroll-behavior: contain; scrollbar-gutter: stable; }
.tm-compact-create.rail-is-open { display: none; }
.tm-modal-foot { display: flex; align-items: center; gap: 10px; padding: 14px 22px; border-top: 1px solid var(--border); background: var(--surface-2); flex: none; }
.tm-form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 15px 16px; }
.tm-field { display: flex; flex-direction: column; }
.tm-field.full { grid-column: 1 / -1; }
.tm-field label { font-size: 12px; font-weight: 700; color: var(--text-2); margin-bottom: 6px; }
.tm-input, .tm-select, .tm-textarea { width: 100%; border-radius: 9px; border: 1px solid var(--border-strong); background: var(--surface); padding: 0 12px; font-family: inherit; font-size: 13px; color: var(--text); outline: none; box-sizing: border-box; }
.tm-input, .tm-select { height: 40px; }
.tm-textarea { padding: 10px 12px; min-height: 84px; resize: vertical; line-height: 1.55; }
.tm-input:focus, .tm-select:focus, .tm-textarea:focus { border-color: var(--accent); box-shadow: var(--ring); }
.tm-prichip-row { display: flex; gap: 8px; }
.tm-prichip { flex: 1; height: 38px; border-radius: 9px; border: 1.5px solid var(--border); background: var(--surface); font-weight: 700; font-size: 12.5px; font-family: inherit; color: var(--text-2); display: inline-flex; align-items: center; justify-content: center; gap: 6px; }
.tm-prichip.on { color: #fff; border-color: transparent; }
.tm-people-pick { display: flex; flex-wrap: wrap; gap: 6px; }
.tm-people-chip { display: inline-flex; align-items: center; gap: 6px; padding: 4px 9px 4px 4px; border-radius: 99px; background: var(--surface-3); font-size: 12px; font-weight: 700; cursor: pointer; border: 1.5px solid transparent; }
.tm-people-chip.on { border-color: var(--accent); background: var(--accent-soft); color: var(--accent); }

/* dropdown menu (shared) */
.tm-menu { position: absolute; background: var(--surface); border: 1px solid var(--border); border-radius: 12px; box-shadow: var(--shadow-lg); padding: 6px; z-index: 95; min-width: 200px; max-height: 320px; overflow-y: auto; }
.tm-mitem { display: flex; align-items: center; gap: 10px; height: 34px; padding: 0 11px; border-radius: 8px; font-size: 13px; font-weight: 600; color: var(--text); cursor: pointer; }
.tm-mitem:hover { background: var(--surface-3); }
.tm-mitem svg { width: 15px; height: 15px; flex: none; }
.tm-msep { height: 1px; background: var(--border); margin: 5px 0; }

.people-search-picker { width: 100%; margin-top: 6px; border: 1px solid var(--border); border-radius: 12px; background: var(--surface); box-shadow: 0 1px 2px rgba(15,23,42,.04); overflow: hidden; }
.people-search-picker.disabled { opacity: .72; background: var(--surface-2); }
.people-search-selected { display: flex; flex-wrap: wrap; gap: 6px; min-height: 36px; padding: 7px; border-bottom: 1px solid var(--border); }
.people-search-chip { display: inline-flex; align-items: center; gap: 6px; max-width: 100%; border: 1px solid rgba(80,70,229,.18); background: var(--accent-soft); color: var(--accent); border-radius: 999px; padding: 5px 8px; font-size: 11.5px; font-weight: 800; }
.people-search-chip span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.people-search-chip button { border: 0; background: transparent; color: inherit; cursor: pointer; display: inline-flex; padding: 0; }
.people-search-placeholder { color: var(--text-3); font-size: 12px; font-weight: 700; align-self: center; padding-left: 2px; }
.people-search-input { display: flex; align-items: center; gap: 7px; padding: 8px 9px; background: var(--surface-2); border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 1; }
.people-search-input input { flex: 1; height: 28px; border: 0; outline: 0; background: transparent; color: var(--text); font: 600 12px var(--font-ui); min-width: 0; }
.people-search-input input::placeholder { color: var(--text-3); font-weight: 600; }
.people-search-input button { border: 0; background: transparent; color: var(--text-3); cursor: pointer; display: inline-flex; padding: 2px; }
.people-search-list { max-height: 220px; overflow-y: auto; padding: 6px; }
.people-search-option { width: 100%; display: flex; align-items: center; gap: 9px; border: 0; background: transparent; color: var(--text); text-align: left; border-radius: 10px; padding: 8px; cursor: pointer; }
.people-search-option:hover, .people-search-option:focus-visible { background: var(--surface-2); outline: 0; }
.people-search-option.on { background: var(--accent-soft); color: var(--accent); }
.people-search-text { min-width: 0; display: flex; flex-direction: column; gap: 2px; font-size: 12px; font-weight: 800; }
.people-search-text span, .people-search-text small { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.people-search-text small { color: var(--text-3); font-size: 11px; font-weight: 700; }
.people-search-empty { padding: 18px 10px; color: var(--text-3); text-align: center; font-size: 12px; font-weight: 700; }
.people-search-menu { padding: 0; overflow: hidden; max-height: none; }
.people-search-menu .people-search-picker { margin-top: 0; border: 0; box-shadow: none; border-radius: 12px; }

/* templates */
.tm-tpl-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 16px; }
.tm-tpl-card { border: 1px solid var(--border); border-radius: 14px; background: var(--surface); padding: 18px; transition: .14s; }
.tm-tpl-card:hover { border-color: var(--border-strong); box-shadow: var(--shadow-sm); }
.tm-tpl-ic { width: 44px; height: 44px; border-radius: 12px; display: grid; place-items: center; margin-bottom: 13px; }
.tm-tpl-steps { display: flex; flex-direction: column; gap: 6px; margin: 13px 0; }
.tm-tpl-step { display: flex; align-items: center; gap: 9px; font-size: 12px; color: var(--text-2); }
.tm-tpl-step .n { width: 18px; height: 18px; border-radius: 99px; background: var(--surface-3); font-size: 10px; font-weight: 800; display: grid; place-items: center; color: var(--text-3); flex: none; }

/* permission matrix */
.tm-perm-table { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.tm-perm-table th, .tm-perm-table td { padding: 10px 12px; text-align: center; border-bottom: 1px solid var(--border); }
.tm-perm-table th { font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .03em; color: var(--text-3); }
.tm-perm-table td:first-child, .tm-perm-table th:first-child { text-align: left; font-weight: 700; color: var(--text); position: sticky; left: 0; background: var(--surface); }
.tm-perm-yes { color: var(--green); }
.tm-perm-no { color: var(--text-3); opacity: .4; }
.tm-perm-own { font-size: 10px; font-weight: 800; color: var(--orange); background: var(--orange-soft); border-radius: 5px; padding: 2px 6px; }

@media (max-width: 1200px){ .tm-dr-side { display: none; } }
@media (max-width: 1000px){ .tm-rail { width: 200px; flex-basis: 200px; } }
@media (max-width: 820px){
  .tm-compact-create.rail-is-open { display: inline-flex; }
  .tm-rail { display: none; }
  .tm-compactbar, .tm-options-panel { padding-left: 14px; padding-right: 14px; }
  .tm-compact-title { min-width: 120px; }
  .tm-search { min-width: 100%; }
  .tm-viewseg { overflow-x: auto; max-width: 100%; }
  .tm-new.compact, .tm-tbtn { height: 34px; padding-left: 10px; padding-right: 10px; font-size: 12px; }
}

/* ============================================================
   Calendar Management module
   ============================================================ */
.cal { display: flex; flex-direction: column; height: 100%; min-height: 0; background: var(--surface-2); position: relative; }
.cal-head { padding: 18px 24px 0; flex: none; }
.cal-primarybar { display: flex; align-items: center; gap: 10px; padding: 14px 24px; border-bottom: 1px solid var(--border); flex: none; flex-wrap: wrap; background: var(--surface); }
.cal-control-btn { height: 36px; padding: 0 13px; border-radius: 9px; border: 1px solid var(--border); background: var(--surface); color: var(--text); font-family: inherit; font-size: 12.5px; font-weight: 800; display: inline-flex; align-items: center; gap: 7px; cursor: pointer; }
.cal-control-btn:hover { border-color: var(--border-strong); box-shadow: var(--shadow-sm); }
.cal-control-btn svg { width: 15px; height: 15px; }
.cal-options-panel { flex: none; border-bottom: 1px solid var(--border); background: var(--surface-2); overflow: visible; }
.cal-options-panel.closed { display: none; }
.cal-compact-warning { display: flex; align-items: center; gap: 8px; margin: 10px 24px 0; padding: 9px 12px; border: 1px solid rgba(245,158,11,.22); border-radius: 11px; background: var(--orange-soft); color: var(--orange); font-size: 12px; font-weight: 700; flex: none; }
.cal-fullscreen { position: fixed; inset: 0; z-index: 70; width: 100vw; height: 100vh; background: var(--surface-2); box-shadow: 0 0 0 9999px rgba(15,18,32,.32); }
.cal-fullscreen .cal-body { flex: 1 1 auto; min-height: 0; }
.cal-fullscreen .cal-month { padding-bottom: 24px; }
.cal-toolbar { display: flex; align-items: center; gap: 10px; padding: 14px 24px; border-bottom: 1px solid var(--border); flex: none; flex-wrap: wrap; background: var(--surface); }
.cal-toolbar { min-width: 0; }
.cal-body { flex: 1; overflow: auto; min-height: 0; }

/* summary cards */
.cal-summary { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; padding: 16px 24px 4px; }
.cal-sum { background: var(--surface); border: 1px solid var(--border); border-radius: 13px; padding: 13px 15px; display: flex; align-items: center; gap: 12px; cursor: pointer; transition: .14s; }
.cal-sum:hover { border-color: var(--border-strong); box-shadow: var(--shadow-sm); }
.cal-sum.on { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
.cal-sum-ic { width: 38px; height: 38px; border-radius: 11px; display: grid; place-items: center; flex: none; }
.cal-sum-n { font-family: var(--font-display); font-weight: 800; font-size: 22px; letter-spacing: -.03em; line-height: 1; }
.cal-sum-l { font-size: 11.5px; font-weight: 600; color: var(--text-3); margin-top: 3px; }

/* nav cluster */
.cal-navbtns { display: inline-flex; align-items: center; gap: 4px; }
.cal-navbtns button { width: 34px; height: 34px; border-radius: 9px; border: 1px solid var(--border); background: var(--surface); display: grid; place-items: center; color: var(--text-2); }
.cal-navbtns button:hover { border-color: var(--border-strong); color: var(--text); }
.cal-today-btn { height: 34px; padding: 0 13px; border-radius: 9px; border: 1px solid var(--border); background: var(--surface); font-weight: 700; font-size: 12.5px; color: var(--text); font-family: inherit; }
.cal-today-btn:hover { border-color: var(--border-strong); }
.cal-period { font-size: 17px; font-weight: 800; letter-spacing: -.02em; min-width: 180px; }

.cal-viewseg { display: inline-flex; background: var(--surface-3); border-radius: 9px; padding: 3px; gap: 2px; flex-wrap: wrap; min-width: 0; overflow-x: auto; scrollbar-width: thin; }
.cal-viewseg button { flex: 0 0 auto; white-space: nowrap; }
.cal-viewseg button { height: 30px; padding: 0 11px; border: none; background: none; border-radius: 7px; font-family: inherit; font-size: 12.5px; font-weight: 700; color: var(--text-3); display: inline-flex; align-items: center; gap: 6px; }
.cal-viewseg button svg { width: 14px; height: 14px; }
.cal-viewseg button.on { background: var(--surface); color: var(--text); box-shadow: var(--shadow-sm); }

.cal-new { height: 36px; padding: 0 15px; border-radius: 9px; border: none; background: var(--accent); color: #fff; font-weight: 800; font-size: 13px; font-family: inherit; display: inline-flex; align-items: center; gap: 7px; box-shadow: 0 5px 14px -5px rgba(79,70,229,.5); }
.cal-new:hover { background: var(--accent-press); }
.cal-new svg { width: 16px; height: 16px; }

.cal-search { display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 11px; border-radius: 9px; background: var(--surface-3); border: 1px solid transparent; color: var(--text-3); min-width: 180px; }
.cal-search:focus-within { background: var(--surface); border-color: var(--accent); box-shadow: var(--ring); }
.cal-search input { border: none; background: none; outline: none; flex: 1; color: var(--text); font-family: inherit; font-size: 13px; min-width: 0; }

/* type legend */
.cal-legend { display: flex; flex-wrap: wrap; gap: 10px 14px; padding: 12px 24px; border-bottom: 1px solid var(--border); background: var(--surface); }
.cal-legend-item { display: inline-flex; align-items: center; gap: 6px; font-size: 11.5px; font-weight: 600; color: var(--text-2); cursor: pointer; opacity: 1; transition: .12s; }
.cal-legend-item.off { opacity: .35; }
.cal-legend-dot { width: 10px; height: 10px; border-radius: 4px; }

/* ===== MONTH GRID ===== */
.cal-month { padding: 18px 24px 40px; }
.cal-month-grid { display: grid; grid-template-columns: repeat(7, 1fr); background: var(--border); border: 1px solid var(--border); border-radius: 13px; overflow: hidden; gap: 1px; }
.cal-dow { background: var(--surface); padding: 9px 12px; font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: .04em; color: var(--text-3); text-align: center; }
.cal-cell { background: var(--surface); min-height: 118px; padding: 7px; display: flex; flex-direction: column; gap: 3px; cursor: pointer; transition: background .1s; }
.cal-cell:hover { background: var(--surface-2); }
.cal-cell.dim { background: var(--surface-2); }
.cal-cell.dim .cal-cell-date { color: var(--text-3); opacity: .6; }
.cal-cell-date { font-size: 12.5px; font-weight: 700; color: var(--text-2); align-self: flex-start; width: 24px; height: 24px; display: grid; place-items: center; border-radius: 99px; }
.cal-cell.today .cal-cell-date { background: var(--accent); color: #fff; }
.cal-ev { display: flex; align-items: center; gap: 5px; font-size: 11px; font-weight: 600; padding: 2px 6px; border-radius: 6px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; cursor: pointer; border-left: 3px solid; }
.cal-ev .cal-ev-time { font-weight: 800; opacity: .85; font-size: 10px; }
.cal-ev.done { opacity: .55; text-decoration: line-through; }
.cal-ev-more { font-size: 10.5px; font-weight: 700; color: var(--text-3); padding-left: 5px; cursor: pointer; }

/* ===== WEEK / DAY TIME GRID ===== */
.cal-timegrid { display: flex; flex-direction: column; padding: 0 24px 40px; }
.cal-tg-header { display: grid; position: sticky; top: 0; background: var(--surface-2); z-index: 3; border-bottom: 1px solid var(--border); }
.cal-tg-corner { width: 60px; flex: none; }
.cal-tg-daycol { padding: 10px 6px; text-align: center; border-left: 1px solid var(--border); }
.cal-tg-daycol .dow { font-size: 11px; font-weight: 700; color: var(--text-3); text-transform: uppercase; }
.cal-tg-daycol .dnum { font-size: 19px; font-weight: 800; letter-spacing: -.02em; margin-top: 2px; }
.cal-tg-daycol.today .dnum { color: #fff; background: var(--accent); width: 30px; height: 30px; border-radius: 99px; display: inline-grid; place-items: center; }
.cal-tg-scroll { position: relative; }
.cal-tg-row { display: grid; height: 52px; }
.cal-tg-time { width: 60px; flex: none; font-size: 10.5px; font-weight: 700; color: var(--text-3); text-align: right; padding-right: 8px; transform: translateY(-7px); }
.cal-tg-slot { border-top: 1px solid var(--border); border-left: 1px solid var(--border); position: relative; cursor: pointer; }
.cal-tg-slot:hover { background: var(--surface); }
.cal-tg-events { position: absolute; inset: 0; pointer-events: none; }
.cal-tg-event { position: absolute; border-radius: 8px; padding: 4px 8px; font-size: 11px; font-weight: 700; color: #fff; overflow: hidden; cursor: pointer; pointer-events: auto; border-left: 3px solid rgba(0,0,0,.18); box-shadow: var(--shadow-sm); }
.cal-tg-event .et { font-size: 10px; font-weight: 700; opacity: .9; }
.cal-now-line { position: absolute; left: 60px; right: 0; height: 2px; background: var(--red); z-index: 4; pointer-events: none; }
.cal-now-line::before { content: ""; position: absolute; left: -5px; top: -4px; width: 10px; height: 10px; border-radius: 99px; background: var(--red); }

/* ===== LIST VIEW ===== */
.cal-list { padding: 8px 0 40px; }
.cal-list-day { padding: 12px 24px 6px; font-size: 12px; font-weight: 800; color: var(--text-3); text-transform: uppercase; letter-spacing: .04em; position: sticky; top: 0; background: var(--surface-2); z-index: 2; }
.cal-list-row { display: flex; align-items: center; gap: 14px; padding: 12px 24px; border-bottom: 1px solid var(--border); cursor: pointer; }
.cal-list-row:hover { background: var(--surface); }
.cal-list-time { width: 120px; flex: none; }
.cal-list-time .t1 { font-weight: 800; font-size: 13.5px; }
.cal-list-time .t2 { font-size: 11.5px; color: var(--text-3); font-weight: 600; }
.cal-list-bar { width: 4px; align-self: stretch; border-radius: 99px; flex: none; }
.cal-list-main { flex: 1; min-width: 0; }
.cal-list-title { font-weight: 700; font-size: 13.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.cal-list-meta { display: flex; align-items: center; gap: 10px; margin-top: 4px; font-size: 11.5px; color: var(--text-3); font-weight: 600; flex-wrap: wrap; }
.cal-list-meta .m { display: inline-flex; align-items: center; gap: 4px; }
.cal-list-meta svg { width: 13px; height: 13px; }

/* ===== EMPLOYEE / TEAM LANES ===== */
.cal-lanes { padding: 4px 0 40px; }
.cal-lane { display: flex; border-bottom: 1px solid var(--border); min-height: 64px; }
.cal-lane-head { width: 190px; flex: none; padding: 12px 16px 12px 24px; display: flex; align-items: center; gap: 10px; border-right: 1px solid var(--border); position: sticky; left: 0; background: var(--surface-2); z-index: 1; }
.cal-lane-name { font-weight: 700; font-size: 13px; }
.cal-lane-sub { font-size: 11px; color: var(--text-3); font-weight: 600; }
.cal-lane-track { flex: 1; display: grid; grid-template-columns: repeat(7, 1fr); gap: 1px; background: var(--border); }
.cal-lane-cell { background: var(--surface); padding: 5px; display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.cal-lane-cell.today { background: var(--accent-soft); }
.cal-lane-pill { font-size: 10px; font-weight: 700; padding: 2px 6px; border-radius: 5px; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; cursor: pointer; }
.cal-lanes-dow { display: flex; padding-left: 190px; border-bottom: 1px solid var(--border); position: sticky; top: 0; background: var(--surface-2); z-index: 2; }
.cal-lanes-dow > div { flex: 1; text-align: center; padding: 8px 4px; font-size: 11px; font-weight: 700; color: var(--text-3); }
.cal-lanes-dow > div.today { color: var(--accent); }

