/* ===== EVENT DETAIL DRAWER ===== */
.cal-drawer-scrim { position: fixed; inset: 0; background: rgba(15,18,32,.42); z-index: 80; display: flex; justify-content: flex-end; animation: tmFade .16s; }
.cal-drawer { width: 460px; max-width: 96vw; background: var(--surface); height: 100%; display: flex; flex-direction: column; box-shadow: -16px 0 48px -16px rgba(0,0,0,.4); animation: tmSlide .22s cubic-bezier(.2,.7,.3,1); }
.cal-dr-banner { height: 6px; flex: none; }
.cal-dr-head { padding: 18px 22px 16px; border-bottom: 1px solid var(--border); }
.cal-dr-type { display: inline-flex; align-items: center; gap: 6px; font-size: 11.5px; font-weight: 800; padding: 3px 9px; border-radius: 7px; margin-bottom: 12px; }
.cal-dr-title { font-size: 20px; font-weight: 800; letter-spacing: -.02em; line-height: 1.25; }
.cal-dr-body { flex: 1; overflow-y: auto; padding: 18px 22px 30px; }
.cal-dr-row { display: flex; gap: 12px; padding: 11px 0; border-bottom: 1px solid var(--border); }
.cal-dr-row:last-child { border-bottom: none; }
.cal-dr-ic { width: 34px; height: 34px; border-radius: 10px; background: var(--surface-3); display: grid; place-items: center; color: var(--text-2); flex: none; }
.cal-dr-ic svg { width: 16px; height: 16px; }
.cal-dr-k { font-size: 11px; font-weight: 700; color: var(--text-3); margin-bottom: 2px; }
.cal-dr-v { font-size: 13.5px; font-weight: 600; }
.cal-dr-foot { display: flex; align-items: center; gap: 8px; padding: 14px 22px; border-top: 1px solid var(--border); background: var(--surface-2); flex-wrap: wrap; }
.cal-conflict { display: flex; align-items: center; gap: 9px; padding: 10px 13px; border-radius: 10px; background: var(--orange-soft); color: var(--orange); font-size: 12.5px; font-weight: 600; margin-top: 12px; }

/* event chips for assignees in drawer */
.cal-people { display: flex; flex-wrap: wrap; gap: 6px; }

/* responsive */
@media (max-width: 1100px){ .cal-summary { grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); } }
@media (max-width: 760px){
  .cal-primarybar { gap: 8px; padding: 12px 14px; }
  .cal-control-btn, .cal-new, .cal-today-btn { height: 34px; padding: 0 10px; font-size: 12px; }
  .cal-toolbar { gap: 8px; }
  .cal-search { min-width: 100%; }
  .cal-period { min-width: 120px; font-size: 15px; }
  .cal-summary { padding: 12px 14px 4px; }
  .cal-toolbar, .cal-legend { padding-left: 14px; padding-right: 14px; }
  .cal-compact-warning { margin-left: 14px; margin-right: 14px; }
  .cal-cell { min-height: 80px; }
  .cal-lane-head { width: 130px; }
  .cal-lanes-dow { padding-left: 130px; }
}

