/* ===== SERVER-RENDERED BLADE DASHBOARD FALLBACK ===== */
.blade-dashboard {
  min-height: 100vh;
  padding: 24px;
  background: var(--bg, #f6f8fb);
  color: var(--text, #0f172a);
}
.blade-dashboard-layout {
  display: grid;
  grid-template-columns: 285px minmax(0, 1fr);
  gap: 20px;
  align-items: start;
  max-width: 1680px;
  margin: 0 auto;
}
.blade-dashboard-sidebar {
  position: sticky;
  top: 24px;
  max-height: calc(100vh - 48px);
  overflow: auto;
  padding: 16px;
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 20px;
  background: var(--surface, #fff);
  box-shadow: var(--shadow-sm, 0 1px 2px rgb(15 23 42 / .08));
}
.blade-sidebar-brand {
  display: grid;
  gap: 4px;
  margin-bottom: 14px;
  padding: 13px 14px;
  border-radius: 15px;
  background: linear-gradient(135deg, var(--accent, #F5852B), #1e293b);
  color: #fff;
}
.blade-sidebar-brand strong {
  font: 900 18px var(--font-display, system-ui, sans-serif);
  letter-spacing: -.03em;
}
.blade-sidebar-brand span {
  color: rgb(255 255 255 / .78);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.blade-sidebar-nav {
  display: grid;
  gap: 13px;
}
.blade-sidebar-group {
  display: grid;
  gap: 5px;
}
.blade-sidebar-group h2 {
  margin: 0 0 3px;
  padding: 0 6px;
  color: var(--text-3, #64748b);
  font: 900 10px var(--font-ui, system-ui, sans-serif);
  letter-spacing: .07em;
  text-transform: uppercase;
}
.blade-sidebar-link {
  display: flex;
  align-items: center;
  min-height: 36px;
  padding: 8px 10px;
  border: 1px solid transparent;
  border-radius: 11px;
  color: var(--text-2, #334155);
  text-decoration: none;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.25;
}
.blade-sidebar-link:hover,
.blade-sidebar-link:focus,
.blade-sidebar-link.is-active {
  border-color: var(--accent, #F5852B);
  background: var(--accent-soft, rgb(37 99 235 / .09));
  color: var(--accent, #F5852B);
  outline: none;
}
.blade-sidebar-link.is-disabled {
  opacity: .45;
  cursor: not-allowed;
}
.blade-sidebar-link.is-disabled:hover {
  border-color: transparent;
  background: transparent;
  color: var(--text-2, #334155);
}
.blade-dashboard-noscript {
  padding: 16px 24px;
  background: #fff7ed;
  color: #9a3412;
  font: 700 13px var(--font-ui, system-ui, sans-serif);
}
.blade-dashboard-shell {
  display: grid;
  gap: 18px;
  max-width: 1320px;
  margin: 0 auto;
}
.blade-dashboard-hero,
.blade-dashboard-card {
  border: 1px solid var(--border, #e2e8f0);
  background: var(--surface, #fff);
  border-radius: 18px;
  box-shadow: var(--shadow-sm, 0 1px 2px rgb(15 23 42 / .08));
}
.blade-dashboard-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 22px;
}
.blade-dashboard-hero h1 {
  margin: 4px 0 8px;
  font: 850 28px var(--font-display, system-ui, sans-serif);
  letter-spacing: -.035em;
}
.blade-dashboard-hero p {
  max-width: 720px;
  color: var(--text-3, #64748b);
  font-size: 13px;
  line-height: 1.55;
}
.blade-dashboard-eyebrow,
.blade-dashboard-label {
  color: var(--text-3, #64748b);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .05em;
  text-transform: uppercase;
}
.blade-dashboard-meta {
  min-width: 210px;
  padding: 13px 15px;
  border-radius: 14px;
  background: var(--surface-2, #f8fafc);
  border: 1px solid var(--border, #e2e8f0);
}
.blade-dashboard-meta span,
.blade-dashboard-meta small {
  display: block;
  color: var(--text-3, #64748b);
  font-size: 11px;
  font-weight: 700;
}
.blade-dashboard-meta strong {
  display: block;
  margin: 5px 0 7px;
  font-size: 18px;
  text-transform: capitalize;
}
.blade-dashboard-kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(165px, 1fr));
  gap: 14px;
}
.blade-dashboard-card {
  padding: 16px;
}
.blade-dashboard-value {
  display: block;
  margin-top: 7px;
  font: 850 24px var(--font-display, system-ui, sans-serif);
}
.blade-dashboard-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.6fr) minmax(320px, .9fr);
  gap: 16px;
  align-items: start;
}
.blade-dashboard-stack {
  display: grid;
  gap: 16px;
}
.blade-dashboard-section-title {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}
.blade-dashboard-section-title h2 {
  margin-top: 3px;
  font: 800 16px var(--font-display, system-ui, sans-serif);
}
.blade-dashboard-section-title small {
  color: var(--text-3, #64748b);
  font-size: 11px;
  font-weight: 700;
}
.blade-module-nav {
  display: grid;
  gap: 16px;
}
.blade-module-group {
  display: grid;
  gap: 9px;
}
.blade-module-group h3 {
  margin: 0;
  color: var(--text-3, #64748b);
  font: 800 11px var(--font-ui, system-ui, sans-serif);
  letter-spacing: .05em;
  text-transform: uppercase;
}
.blade-module-links {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(185px, 1fr));
  gap: 9px;
}
.blade-module-link {
  display: block;
  min-height: 58px;
  padding: 11px 12px;
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 13px;
  background: var(--surface-2, #f8fafc);
  color: var(--text, #0f172a);
  text-decoration: none;
  transition: border-color .16s ease, transform .16s ease, box-shadow .16s ease;
}
.blade-module-link:hover,
.blade-module-link:focus {
  border-color: var(--accent, #4f46e5);
  box-shadow: var(--shadow-sm, 0 1px 2px rgb(15 23 42 / .08));
  outline: none;
  transform: translateY(-1px);
}
.blade-module-link span,
.blade-module-link small {
  display: block;
}
.blade-module-link span {
  font-size: 12px;
  font-weight: 800;
}
.blade-module-link small {
  margin-top: 4px;
  color: var(--text-3, #64748b);
  font-size: 10.5px;
  font-weight: 700;
}
.blade-module-link.is-disabled {
  opacity: .58;
  cursor: not-allowed;
}
.blade-module-link.is-disabled:hover {
  border-color: var(--border, #e2e8f0);
  box-shadow: none;
  transform: none;
}
.blade-dashboard-table-wrap {
  overflow-x: auto;
}
.blade-dashboard-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}
.blade-dashboard-table th,
.blade-dashboard-table td {
  padding: 10px;
  border-bottom: 1px solid var(--border, #e2e8f0);
  text-align: left;
  vertical-align: top;
}
.blade-dashboard-table th {
  color: var(--text-3, #64748b);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.blade-dashboard-table td span {
  display: block;
  margin-top: 3px;
  color: var(--text-3, #64748b);
  font-size: 11px;
}
.blade-dashboard-funnel,
.blade-dashboard-list {
  display: grid;
  gap: 9px;
}
.blade-dashboard-funnel div,
.blade-dashboard-list div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 11px;
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 12px;
  background: var(--surface-2, #f8fafc);
}
.blade-dashboard-list div {
  display: block;
}
.blade-dashboard-funnel span,
.blade-dashboard-list span {
  color: var(--text-3, #64748b);
  font-size: 11px;
  font-weight: 700;
}
.blade-dashboard-list span {
  display: block;
  margin-top: 4px;
}
.blade-dashboard-note {
  padding: 12px 14px;
  border: 1px dashed var(--border, #e2e8f0);
  border-radius: 14px;
  color: var(--text-3, #64748b);
  background: var(--surface, #fff);
  font-size: 12px;
  font-weight: 700;
}
@media (max-width: 900px) {
  .blade-dashboard { padding: 14px; }
  .blade-dashboard-layout { grid-template-columns: 1fr; }
  .blade-dashboard-sidebar {
    position: static;
    max-height: none;
  }
  .blade-sidebar-nav {
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  }
  .blade-dashboard-hero { flex-direction: column; }
  .blade-dashboard-meta { width: 100%; }
  .blade-dashboard-grid { grid-template-columns: 1fr; }
}

/* ===== NATIVE BLADE WORKSPACES ===== */
.blade-workspace-body {
  margin: 0;
  background: var(--bg, #f6f8fb);
  color: var(--text, #0f172a);
}
.blade-workspace-body > .blade-dashboard-sidebar {
  position: fixed;
  inset: 24px auto 24px 24px;
  width: 285px;
  max-height: calc(100vh - 48px);
  z-index: 10;
}
.blade-workspace-body > .blade-dashboard-sidebar + .blade-workspace {
  max-width: none;
  margin: 0 24px 0 333px;
}
.blade-workspace {
  display: grid;
  gap: 18px;
  max-width: 1360px;
  min-height: 100vh;
  margin: 0 auto;
  padding: 24px;
}
.blade-workspace-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 22px;
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 18px;
  background: var(--surface, #fff);
  box-shadow: var(--shadow-sm, 0 1px 2px rgb(15 23 42 / .08));
}
.blade-workspace-header h1 {
  margin: 4px 0 8px;
  font: 850 28px var(--font-display, system-ui, sans-serif);
  letter-spacing: -.035em;
}
.blade-workspace-header p {
  max-width: 760px;
  color: var(--text-3, #64748b);
  font-size: 13px;
  line-height: 1.55;
}
.blade-workspace-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
}
.blade-workspace-actions a,
.blade-primary-action,
.blade-secondary-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 38px;
  padding: 0 13px;
  border-radius: 10px;
  border: 1px solid var(--border, #e2e8f0);
  background: var(--surface, #fff);
  color: var(--text, #0f172a);
  font: 800 12px var(--font-ui, system-ui, sans-serif);
  text-decoration: none;
  cursor: pointer;
}
.blade-primary-action {
  border-color: var(--accent, #F5852B);
  background: var(--accent, #F5852B);
  color: #fff;
}
.blade-secondary-action:hover,
.blade-workspace-actions a:hover {
  border-color: var(--accent, #F5852B);
}
.blade-alert {
  padding: 13px 15px;
  border-radius: 14px;
  font-size: 12px;
  font-weight: 700;
}
.blade-alert ul {
  margin: 8px 0 0 18px;
}
.blade-alert-success {
  background: #dcfce7;
  color: #166534;
}
.blade-alert-error {
  background: #fee2e2;
  color: #991b1b;
}
.blade-workspace-grid {
  display: grid;
  grid-template-columns: minmax(0, .95fr) minmax(420px, 1.05fr);
  gap: 16px;
  align-items: start;
}
.blade-score-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(185px, 1fr));
  gap: 10px;
}
.blade-score-card,
.blade-band-list div {
  padding: 12px;
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 12px;
  background: var(--surface-2, #f8fafc);
}
.blade-score-card strong,
.blade-score-card span,
.blade-band-list strong,
.blade-band-list span {
  display: block;
}
.blade-score-card span,
.blade-band-list span {
  margin-top: 4px;
  color: var(--text-3, #64748b);
  font-size: 11px;
  font-weight: 700;
}
.blade-score-card ul {
  margin: 9px 0 0 18px;
  color: var(--text-2, #334155);
  font-size: 11px;
  line-height: 1.55;
}
.blade-band-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 9px;
  margin-top: 12px;
}
.blade-form-grid,
.blade-filter-grid {
  display: grid;
  gap: 12px;
}
.blade-form-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.blade-filter-grid {
  grid-template-columns: repeat(6, minmax(130px, 1fr));
  align-items: end;
  margin-bottom: 14px;
}
.blade-form-grid label,
.blade-filter-grid label {
  color: var(--text-2, #334155);
  font-size: 11px;
  font-weight: 800;
}
.blade-form-grid input,
.blade-form-grid select,
.blade-form-grid textarea,
.blade-filter-grid input,
.blade-filter-grid select {
  display: block;
  width: 100%;
  min-height: 38px;
  margin-top: 6px;
  padding: 0 10px;
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 10px;
  background: var(--surface-2, #f8fafc);
  color: var(--text, #0f172a);
  font: 600 12px var(--font-ui, system-ui, sans-serif);
  outline: 0;
}
.blade-form-grid textarea {
  min-height: 96px;
  padding: 10px;
  resize: vertical;
}
.blade-form-grid input:focus,
.blade-form-grid select:focus,
.blade-form-grid textarea:focus,
.blade-filter-grid input:focus,
.blade-filter-grid select:focus {
  border-color: var(--accent, #F5852B);
  box-shadow: var(--ring, 0 0 0 3px rgb(37 99 235 / .16));
}
.blade-form-wide,
.blade-form-grid .blade-primary-action {
  grid-column: 1 / -1;
}
.blade-fieldset {
  margin: 0;
  padding: 14px;
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 14px;
  background: var(--surface, #fff);
}
.blade-fieldset legend {
  padding: 0 6px;
  color: var(--text, #0f172a);
  font-size: 12px;
  font-weight: 900;
}
.blade-workspace-note {
  margin-top: 12px;
  padding: 11px 12px;
  border: 1px dashed var(--border, #e2e8f0);
  border-radius: 12px;
  color: var(--text-3, #64748b);
  background: var(--surface, #fff);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.55;
}
.blade-workspace-note code {
  color: var(--accent, #F5852B);
}
.blade-dashboard-metrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 10px;
  margin-top: 14px;
}
.blade-dashboard-metric {
  padding: 12px;
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 14px;
  background: var(--surface-2, #f8fafc);
}
.blade-dashboard-metric span {
  display: block;
  color: var(--text-3, #64748b);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .05em;
}
.blade-dashboard-metric strong {
  display: block;
  margin-top: 4px;
  color: var(--text, #0f172a);
  font-size: 22px;
  line-height: 1;
}
.blade-pagination {
  margin-top: 14px;
}
.blade-row-actions {
  min-width: 240px;
  margin: 5px 0;
}
.blade-row-actions summary {
  cursor: pointer;
  color: var(--accent, #F5852B);
  font-size: 11px;
  font-weight: 800;
}
.blade-table-action-stack {
  display: grid;
  gap: 8px;
  min-width: 280px;
}
.blade-inline-form {
  display: grid;
  gap: 7px;
  margin-top: 8px;
  padding: 10px;
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 12px;
  background: var(--surface-2, #f8fafc);
}
.blade-inline-form input,
.blade-inline-form select,
.blade-inline-form textarea {
  width: 100%;
  min-height: 34px;
  padding: 0 9px;
  border: 1px solid var(--border, #e2e8f0);
  border-radius: 9px;
  background: var(--surface, #fff);
  color: var(--text, #0f172a);
  font: 600 11px var(--font-ui, system-ui, sans-serif);
}
.blade-inline-form textarea {
  min-height: 62px;
  padding: 8px 9px;
  resize: vertical;
}
@media (max-width: 1100px) {
  .blade-workspace-grid { grid-template-columns: 1fr; }
  .blade-filter-grid { grid-template-columns: repeat(3, minmax(130px, 1fr)); }
}
@media (max-width: 720px) {
  .blade-workspace-body > .blade-dashboard-sidebar {
    position: static;
    width: auto;
    max-height: none;
    margin: 14px 14px 0;
  }
