/* ===== BUILDER360 STANDALONE SHELL ALIGNMENT FOR BLADE ===== */
.blade-dashboard {
  padding: 0;
  background: transparent;
}

.blade-dashboard-layout {
  display: contents;
}

.blade-dashboard-sidebar.sidebar {
  padding: 0;
  border-radius: 0;
  box-shadow: none;
}

.blade-sidebar-nav {
  display: block;
}

.blade-sidebar-group {
  display: block;
}

.blade-sidebar-group h2.sb-group-label {
  margin: 0;
}

.blade-sidebar-link.nav-item {
  border: 0;
  text-decoration: none;
  min-height: 37px;
  line-height: 1;
}

.blade-sidebar-link.nav-item .ni-ic {
  width: 18px;
  height: 18px;
  flex: 0 0 18px;
  border-radius: 6px;
  display: grid;
  place-items: center;
  background: var(--surface-3);
  color: var(--text-3);
  font-size: 10px;
  font-weight: 900;
}

.blade-sidebar-link.nav-item.active .ni-ic,
.blade-sidebar-link.nav-item:hover .ni-ic {
  background: var(--accent);
  color: #fff;
}

.blade-sidebar-link.nav-item.is-disabled {
  opacity: .42;
  cursor: not-allowed;
}

.blade-dashboard-shell {
  max-width: 1500px;
  margin: 0 auto;
}

.blade-dashboard-hero {
  border: 0;
  background: transparent;
  box-shadow: none;
  border-radius: 0;
  padding: 0;
}

.blade-dashboard-hero h1 {
  margin: 0;
  font-size: 25px;
  font-weight: 800;
  letter-spacing: -.035em;
}

.blade-dashboard-hero p:not(.crumbs) {
  color: var(--text-2);
  font-size: 13.5px;
  margin-top: 3px;
}

.blade-dashboard-meta {
  background: var(--surface);
  border-color: var(--border);
  border-radius: var(--r-lg);
}

.blade-dashboard-card.card {
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-sm);
}

.blade-dashboard-card.card-pad {
  padding: 0;
}

.blade-dashboard-card.card-pad > :not(.card-head) {
  margin-left: 18px;
  margin-right: 18px;
}

.blade-dashboard-card.card-pad > :last-child {
  margin-bottom: 18px;
}

.blade-dashboard-section-title.card-head {
  margin-bottom: 16px;
}

.blade-dashboard-value.stat-val {
  margin-top: 8px;
}

.blade-module-link {
  background: var(--surface);
  border-color: var(--border);
}

.blade-module-link:hover,
.blade-module-link:focus {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.blade-dashboard-table.tbl th,
.blade-dashboard-table.tbl td {
  padding: 13px 16px;
}

.blade-dashboard-table.tbl td span {
  margin-top: 4px;
}

.blade-dashboard-funnel div,
.blade-dashboard-list div {
  background: var(--surface);
}

.blade-dashboard-note,
.blade-workspace-note {
  border-radius: 12px;
  background: var(--surface);
}

.blade-workspace-body {
  display: flex;
  height: 100vh;
  overflow: hidden;
  background: var(--bg-grad);
}

.blade-workspace-body > .blade-dashboard-sidebar.sidebar {
  position: relative;
  inset: auto;
  width: 264px;
  max-height: none;
  height: 100vh;
  z-index: 30;
}

.blade-workspace-body > .blade-dashboard-sidebar + .blade-workspace {
  margin: 0;
}

.blade-workspace {
  flex: 1;
  min-width: 0;
  height: 100vh;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  display: block;
  max-width: none;
  padding: 26px 28px 60px;
}

.blade-workspace-header {
  border: 0;
  background: transparent;
  box-shadow: none;
  border-radius: 0;
  padding: 0;
  margin-bottom: 22px;
  align-items: flex-end;
}

.blade-workspace-header h1 {
  margin: 0;
  font-size: 25px;
  font-weight: 800;
  letter-spacing: -.035em;
}

.blade-workspace-header p {
  color: var(--text-2);
  font-size: 13.5px;
  margin-top: 3px;
}

.blade-workspace-actions a,
.blade-primary-action,
.blade-secondary-action {
  min-height: 38px;
  padding: 0 15px;
  border-radius: 9px;
  border-color: var(--border-strong);
  font-size: 13px;
  font-weight: 700;
}

.blade-primary-action {
  border-color: transparent;
  background: var(--accent);
  box-shadow: 0 4px 12px -3px rgba(79,70,229,.45);
}

.blade-workspace-grid {
  gap: 16px;
}

.blade-form-grid input,
.blade-form-grid select,
.blade-form-grid textarea,
.blade-filter-grid input,
.blade-filter-grid select,
.blade-inline-form input,
.blade-inline-form select,
.blade-inline-form textarea {
  border-color: var(--border-strong);
  background: var(--surface);
  border-radius: 9px;
}

@media (max-width: 940px) {
  .blade-workspace-body {
    display: block;
    height: auto;
    overflow: auto;
  }

  .blade-workspace-body > .blade-dashboard-sidebar.sidebar {
    position: static;
    width: auto;
    height: auto;
    margin: 14px;
    border-radius: var(--r-lg);
    box-shadow: var(--shadow-sm);
  }

  .blade-workspace {
    height: auto;
    min-height: 100vh;
    overflow: visible;
    padding: 14px;
  }

  .blade-dashboard .topbar {
    flex-wrap: wrap;
    height: auto;
    padding: 12px 14px;
  }

  .blade-dashboard .page {
    padding: 18px 14px 50px;
  }
}
