.b360-email-recipient-section{display:grid;border:1px solid var(--border);border-radius:13px;background:var(--surface)}.b360-email-recipient-row{display:grid;grid-template-columns:42px minmax(0,1fr) auto;align-items:start;gap:8px;min-height:48px;padding:7px 10px;border-bottom:1px solid var(--border)}.b360-email-recipient-row:last-of-type{border-bottom:0}.b360-email-recipient-row>span{padding-top:9px;color:var(--muted);font-size:13px;font-weight:800}.b360-email-token-field{display:flex;align-items:center;flex-wrap:wrap;gap:6px;min-width:0}.b360-email-token-field>input{flex:1;min-width:180px;height:34px;border:0;background:transparent;color:var(--text);font:inherit;outline:none}.b360-email-token{display:inline-flex;align-items:center;gap:5px;max-width:100%;padding:5px 7px 5px 10px;border:1px solid #d8d5ff;border-radius:999px;background:#f2f1ff;color:var(--text);font-size:12px}.b360-email-token>span{max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.b360-email-token button{display:grid;place-items:center;width:20px;height:20px;border:0;border-radius:50%;background:transparent;color:var(--muted);cursor:pointer}.b360-email-token button:hover{background:#dedbff;color:var(--primary)}.b360-recipient-disclosures{display:flex;gap:6px;padding-top:3px}.b360-recipient-disclosures button{border:0;background:transparent;color:var(--primary);font-size:12px;font-weight:800;cursor:pointer}.b360-recipient-error{min-height:0;margin:0;padding:0 12px;color:#b42318;font-size:12px}.b360-recipient-error:not(:empty){padding-bottom:8px}
.b360-email-editor-surface{min-height:220px;max-height:420px;overflow:auto;padding:15px;color:var(--text);line-height:1.55;outline:none}.b360-email-editor-surface:focus{box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--primary) 28%,transparent)}.b360-send-later-field{max-width:310px}.b360-mail-chips a.is-active{border-color:var(--primary);background:#f0efff;color:var(--primary)}
.b360-inline-image-button{display:grid;place-items:center;width:34px;height:32px;border-radius:8px;color:var(--muted);cursor:pointer}.b360-inline-image-button:hover{background:#e9e7ff;color:var(--primary)}.b360-inline-image-button input{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.b360-inline-email-image{display:block;max-width:min(100%,640px);height:auto;margin:10px 0;border-radius:10px}
@media(max-width:760px){.b360-email-recipient-row{grid-template-columns:34px minmax(0,1fr)}.b360-recipient-disclosures{grid-column:2}.b360-email-token-field>input{min-width:130px}.b360-email-editor-surface{min-height:180px}.b360-send-later-field{max-width:none}.b360-mail-account-menu{position:fixed;inset:80px 12px auto;max-height:60vh}}

/* Task collaboration completion */
.tm-live-update{position:fixed;z-index:120;top:82px;left:50%;display:flex;align-items:center;gap:16px;max-width:min(680px,calc(100vw - 24px));padding:10px 12px 10px 16px;border:1px solid #c9c5ff;border-radius:14px;background:var(--surface);box-shadow:0 16px 42px rgba(16,24,40,.18);transform:translateX(-50%)}.tm-live-update>span{display:flex;align-items:center;gap:7px;min-width:0}.tm-live-update i{color:var(--primary)}.tm-live-update .blade-primary-action{white-space:nowrap}
.tm-inline-actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:12px}.tm-inline-actions form{margin:0}
.tm-comment-input-wrap{position:relative;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:8px;flex:1;min-width:0}.tm-comment-input-wrap textarea{grid-column:1}.tm-comment-input-wrap>.tm-iconbtn{grid-column:2;margin-bottom:5px}
.tm-mention-popover{position:absolute;z-index:90;inset:auto 0 calc(100% + 8px) 0;max-height:300px;overflow:hidden;border:1px solid var(--border);border-radius:14px;background:var(--surface);box-shadow:0 18px 44px rgba(16,24,40,.18)}.tm-mention-popover>header{display:grid;gap:2px;padding:11px 13px;border-bottom:1px solid var(--border)}.tm-mention-popover>header small{color:var(--muted)}.tm-mention-popover .tm-mention-list{display:grid;max-height:230px;overflow:auto;padding:6px}.tm-mention-popover .tm-mention-list>button{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:9px;width:100%;padding:8px;border:0;border-radius:10px;background:transparent;color:var(--text);text-align:left;cursor:pointer}.tm-mention-popover .tm-mention-list>button:hover,.tm-mention-popover .tm-mention-list>button:focus-visible{background:var(--surface-soft);outline:2px solid color-mix(in srgb,var(--primary) 30%,transparent)}.tm-mention-popover .tm-mention-list>button>span:last-child{display:grid;min-width:0}.tm-mention-popover .tm-mention-list small{overflow:hidden;color:var(--muted);text-overflow:ellipsis;white-space:nowrap}
@media(max-width:760px){.tm-inline-mention-composer{align-items:stretch}.tm-comment-input-wrap{grid-template-columns:minmax(0,1fr) auto}.tm-mention-popover{position:fixed;inset:auto 12px 76px;max-height:52vh}.tm-inline-actions{display:grid;grid-template-columns:1fr 1fr}.tm-inline-actions button{width:100%}}
.b360-company-mail-account{overflow:hidden;border:1px solid var(--border);border-radius:14px}.b360-company-mail-account>.b360-connected-account{border:0;border-radius:0}.b360-mail-assignment-panel{border-top:1px solid var(--border)}.b360-mail-assignment-panel>summary{padding:11px 14px;color:var(--primary);font-weight:800;cursor:pointer}.b360-mail-assignment-panel>div{display:grid;gap:14px;padding:14px;background:var(--surface-soft)}.b360-mail-assignee-list{display:grid;gap:8px}.b360-mail-assignee-list>div{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 11px;border:1px solid var(--border);border-radius:10px;background:var(--surface)}.b360-mail-assignee-list span:first-child{display:grid}.b360-mail-assignee-list small{color:var(--muted)}

/* Chat Connect conversation rail — accepted from the other-machine UI donor. */
.cc-search-summary{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:8px 12px;padding:9px 11px;border:1px solid var(--border);border-radius:10px;background:var(--surface-soft);color:var(--muted);font-size:12px}.cc-search-summary span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cc-search-summary em{color:var(--text);font-style:normal}.cc-search-summary a{flex:0 0 auto;color:var(--primary);font-weight:800;text-decoration:none}
.cc-section-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:15px 15px 7px}.cc-section-label{margin:0;color:var(--muted);font-size:11px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.cc-section-count{display:grid;place-items:center;min-width:22px;height:22px;padding:0 7px;border:1px solid var(--border);border-radius:999px;background:var(--surface-soft);color:var(--muted);font-size:10px;font-weight:900}
.cc-conv-row{display:grid;grid-template-columns:48px minmax(0,1fr) auto;align-items:center;gap:11px;min-height:70px;margin:2px 8px;padding:9px 10px;border:1px solid transparent;border-radius:14px;color:var(--text);text-decoration:none;transition:background .15s ease,border-color .15s ease,box-shadow .15s ease}.cc-conv-row:hover{border-color:var(--border);background:var(--surface-soft)}.cc-conv-row:focus-visible{outline:3px solid color-mix(in srgb,var(--primary) 25%,transparent);outline-offset:1px}.cc-conv-row.is-active{border-color:color-mix(in srgb,var(--primary) 16%,var(--border));background:color-mix(in srgb,var(--primary) 10%,var(--surface));box-shadow:inset 3px 0 0 var(--primary)}
.cc-conv-avatar{position:relative;display:grid;place-items:center;width:48px;height:48px;overflow:hidden;border-radius:14px;background:var(--primary);color:#fff;font-size:19px;font-weight:900}.cc-conv-avatar.is-channel{border-radius:13px;background:color-mix(in srgb,var(--primary) 13%,var(--surface));color:var(--primary)}.cc-conv-avatar-image{width:100%!important;height:100%!important;border-radius:inherit!important}.cc-conv-copy{display:grid;gap:4px;min-width:0}.cc-conv-name,.cc-conv-preview{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cc-conv-name{font-size:13px;font-weight:850}.cc-conv-preview{color:var(--muted);font-size:12px}.cc-conv-meta{display:grid;align-self:stretch;justify-items:end;align-content:center;gap:7px;min-width:42px}.cc-conv-time{color:var(--muted);font-size:10px;white-space:nowrap}.cc-unread-badge{display:grid;place-items:center;min-width:22px;height:22px;padding:0 6px;border-radius:999px;background:var(--primary);color:#fff;font-size:10px;font-style:normal;font-weight:900}
.cc-empty{display:grid;justify-items:center;gap:8px;padding:34px 18px;text-align:center;color:var(--muted)}.cc-empty strong{color:var(--text)}.cc-empty-icon{display:grid;place-items:center;width:48px;height:48px;border-radius:14px;background:var(--surface-soft);color:var(--muted);font-size:19px}
@media(max-width:760px){.cc-conv-row{grid-template-columns:44px minmax(0,1fr) auto;min-height:64px;margin-inline:6px;padding:8px}.cc-conv-avatar{width:44px;height:44px}.cc-section-head{padding-inline:13px}}
